#include <iostream>
#include <vector>

using namespace std;

struct Child {
    int v, d, p;
    int index;
    bool treated;
};

int main() {
    int n;
    cin >> n;

    vector<Child> children(n);
    for (int i = 0; i < n; i++) {
        cin >> children[i].v >> children[i].d >> children[i].p;
        children[i].index = i + 1;
        children[i].treated = false;
    }

    vector<int> treated;

    for (int i = 0; i < n; i++) {
        if (children[i].treated) continue;

        // Current child gets treated
        children[i].treated = true;
        treated.push_back(children[i].index);

        // Update confidences of remaining children
        for (int j = i + 1; j < i + 1 + children[i].v && j < n; j++) {
            children[j].p -= (children[i].v - (j - i - 1));
        }

        // Check for chain reaction of crying
        bool changed = true;
        while (changed) {
            changed = false;
            for (int j = i + 1; j < n; j++) {
                if (children[j].treated) continue;

                if (children[j].p < 0) {
                    // Child cries and leaves
                    children[j].treated = true;
                    changed = true;

                    // Reduce confidence of all children behind
                    for (int k = j + 1; k < n; k++) {
                        if (!children[k].treated) {
                            children[k].p -= children[j].d;
                        }
                    }
                }
            }
        }
    }

    cout << treated.size() << endl;
    for (int i = 0; i < treated.size(); i++) {
        cout << treated[i] << (i < treated.size() - 1 ? " " : "");
    }
    cout << endl;

    return 0;
}

