        children[i].original_index = i + 1;
    }

    vector<int> treated;

    for (int i = 0; i < children.size(); i++) {
        // Current child gets treated
        treated.push_back(children[i].original_index);

        // Update confidence of remaining children due to crying in the office
        vector<Child> updated_children;
        for (int j = i + 1; j < children.size(); j++) {
            Child c = children[j];
            if (j - i <= children[i].v) {
                c.p -= children[i].v - (j - i - 1);
            }
            updated_children.push_back(c);
        }

        // Handle chain reaction of crying and leaving
        vector<Child> remaining_children;
        for (size_t j = 0; j < updated_children.size(); j++) {
            if (updated_children[j].p >= 0) {
                remaining_children.push_back(updated_children[j]);
            } else {
                // Child cries and leaves
                for (size_t k = j + 1; k < updated_children.size(); k++) {
                    updated_children[k].p -= updated_children[j].d;
                }
            }
        }

        children = remaining_children;
    }

    cout << treated.size() << endl;
    for (size_t i = 0; i < treated.size(); i++) {
