using namespace std;

double dist(double dx, double dy, double v, double wx, double wy) {
    double wind_proj = (dx * wx + dy * wy) / sqrt(dx * dx + dy * dy);
    double perp_wind_x = wx - wind_proj * dx / sqrt(dx * dx + dy * dy);
    double perp_wind_y = wy - wind_proj * dy / sqrt(dx * dx + dy * dy);
    double perp_wind = sqrt(perp_wind_x * perp_wind_x + perp_wind_y * perp_wind_y);

    if (perp_wind >= v) {
        return INFINITY;
    }

    double vres = sqrt(v * v - perp_wind * perp_wind) + wind_proj;
    if (vres <= 0) {
        return INFINITY;
    }

    return sqrt(dx * dx + dy * dy) / vres;
}

