double timeNeeded(double dist, double v, double windX, double windY) {
    double windMagnitude = sqrt(windX * windX + windY * windY);
    if (windMagnitude >= v) {
        return INFINITY; // Cannot reach if wind is stronger than dirigible max speed
    }

    // Calculate time using law of cosines solution
    double a = v * v - windMagnitude * windMagnitude;
    double b = 2 * dist * windMagnitude;
    double c = -dist * dist;

    // Solve quadratic equation at² + bt + c = 0
    return (-b + sqrt(b * b - 4 * a * c)) / (2 * a);
}

int main() {
    int x1, y1, x2, y2;
    std::cin >> x1 >> y1 >> x2 >> y2;

    int v, t;
    std::cin >> v >> t;

    int vx, vy, wx, wy;
    std::cin >> vx >> vy >> wx >> wy;

    double distTotal = distance(x1, y1, x2, y2);
    double time1 = timeNeeded(distTotal, v, vx, vy);

    // If we can reach the destination within time t with the first wind
    if (time1 <= t) {
        std::cout << std::fixed << std::setprecision(15) << time1 << std::endl;
