long long countDivisibleInRange(long long low, long long high, long long divisor) {
    // Calculate the first number >= low that is divisible by divisor
    long long first = low + ((divisor - low % divisor) % divisor);
    if (first > high) {
        return 0;
    }
    // Calculate how many divisible numbers are in the range
    return (high - first) / divisor + 1;
