    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Segment> segments(n);
    set<ll> xCoords, yCoords;

    for (int i = 0; i < n; ++i) {
        cin >> segments[i].x1 >> segments[i].y1 >> segments[i].x2 >> segments[i].y2;

        // Ensure x1 <= x2 and y1 <= y2
        if (segments[i].x1 > segments[i].x2) {
            swap(segments[i].x1, segments[i].x2);
        }
        if (segments[i].y1 > segments[i].y2) {
            swap(segments[i].y1, segments[i].y2);
        }

        xCoords.insert(segments[i].x1);
        xCoords.insert(segments[i].x2);
        yCoords.insert(segments[i].y1);
        yCoords.insert(segments[i].y2);
    }

    // Coordinate compression
    map<ll, int> xMap, yMap;
    int xIdx = 0, yIdx = 0;

    for (ll x : xCoords) {
        xMap[x] = xIdx++;
    }
    for (ll y : yCoords) {
        yMap[y] = yIdx++;
    }

    // Create a 2D grid for compressed coordinates
    vector<vector<bool>> grid(xCoords.size(), vector<bool>(yCoords.size(), false));

    // Mark cells covered by segments
    for (const Segment& seg : segments) {
        if (seg.x1 == seg.x2) {
            // Vertical segment
            int x = xMap[seg.x1];
            for (int y = yMap[seg.y1]; y < yMap[seg.y2]; y++) {
                grid[x][y] = true;
            }
        } else {
            // Horizontal segment
            int y = yMap[seg.y1];
            for (int x = xMap[seg.x1]; x < xMap[seg.x2]; x++) {
                grid[x][y] = true;
            }
        }
    }

    // Count painted cells
    ll count = 0;
    vector<ll> xValues(xCoords.begin(), xCoords.end());
    vector<ll> yValues(yCoords.begin(), yCoords.end());

    for (int i = 0; i < xCoords.size() - 1; ++i) {
        for (int j = 0; j < yCoords.size() - 1; ++j) {
            if (grid[i][j]) {
                count += (xValues[i+1] - xValues[i]) * (yValues[j+1] - yValues[j]);
            }
        }
    }

    cout << count << endl;

    return 0;
}

