    for (const std::string& num : numbers) {
        if (num == "0") {
            hasZero = true;
            break;
        }

        if (num == "1") continue; // Multiplying by 1 doesn't change the result

        // Multiply result by num
        int carry = 0;
        std::string temp;

        for (int i = result.size() - 1; i >= 0; i--) {
