int main() {
    int n, m;
    std::cin >> n >> m;

    std::vector<std::vector<int>> buttons(n);

    // Read the button connections
    for (int i = 0; i < n; i++) {
        int x;
        std::cin >> x;

        for (int j = 0; j < x; j++) {
            int bulb;
            std::cin >> bulb;
            buttons[i].push_back(bulb);
        }
    }

    std::set<int> lit_bulbs;
    bool changed = true;

    // Keep pressing buttons until no more bulbs can be turned on
    while (changed) {
        changed = false;

        for (int i = 0; i < n; i++) {
            bool can_press = false;

            // Check if this button can turn on any new bulbs
            for (int bulb : buttons[i]) {
                if (lit_bulbs.find(bulb) == lit_bulbs.end()) {
                    can_press = true;
                    break;
                }
            }

            // If it can turn on new bulbs, press it
            if (can_press) {
                bool new_bulbs_lit = false;
                for (int bulb : buttons[i]) {
                    if (lit_bulbs.find(bulb) == lit_bulbs.end()) {
                        lit_bulbs.insert(bulb);
                        new_bulbs_lit = true;
                    }
                }

                if (new_bulbs_lit) {
                    changed = true;
                }
            }
        }
    }

    // Check if all m bulbs are lit
    if (lit_bulbs.size() == m) {
        std::cout << "YES" << std::endl;
    } else {
        std::cout << "NO" << std::endl;
    }

    return 0;
}

