#include <iostream>
#include <unordered_map>
#include <vector>

using namespace std;

int main() {
    int n;
    cin >> n;

    vector<pair<int, int>> bishops(n);
    for (int i = 0; i < n; i++) {
        cin >> bishops[i].first >> bishops[i].second;
    }

    // Count bishops on each diagonal
    unordered_map<int, int> diag1; // r + c
    unordered_map<int, int> diag2; // r - c

    for (int i = 0; i < n; i++) {
        int r = bishops[i].first;
        int c = bishops[i].second;
        diag1[r + c]++;
        diag2[r - c]++;
    }

    long long ans = 0;

    // For each diagonal, calculate number of pairs
    for (auto& p : diag1) {
        int count = p.second;
        ans += (long long)count * (count - 1) / 2;
    }

    for (auto& p : diag2) {
        int count = p.second;
        ans += (long long)count * (count - 1) / 2;
    }

    cout << ans << endl;

    return 0;
}

