    long long total_pairs = 0;

    for (int i = 0; i < n; i++) {
        int x, y;
        std::cin >> x >> y;

        // Bishops on the same diagonal \ have the same value of (x - y)
        int d1 = x - y;
        // Bishops on the same diagonal / have the same value of (x + y)
        int d2 = x + y;

        // Add the number of bishops already on these diagonals to the total
        total_pairs += diagonal1[d1];
        total_pairs += diagonal2[d2];

        // Increment the count of bishops on these diagonals
        diagonal1[d1]++;
        diagonal2[d2]++;
    }

    std::cout << total_pairs << std::endl;

    return 0;
