#include <iostream>
#include <vector>

long long gcd(long long a, long long b) {
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

long long lcm(long long a, long long b) {
    return a / gcd(a, b) * b;
}

int main() {
    long long n;
    std::cin >> n;

    // Calculate LCM of all numbers from 2 to 10
    long long result = 1;
    for (int i = 2; i <= 10; ++i) {
        result = lcm(result, i);
    }

    // Count the number of multiples of result in range [1, n]
    std::cout << n / result << std::endl;

    return 0;
}

