    int n, m;
    std::cin >> n >> m;

    std::vector<Block> t(n), s(m);

    // Read string t blocks
    for (int i = 0; i < n; ++i) {
        std::cin >> t[i].length;
        char dash;
        std::cin >> dash; // Read the dash
        std::cin >> t[i].character;
    }

    // Read string s blocks
    for (int i = 0; i < m; ++i) {
        std::cin >> s[i].length;
        char dash;
        std::cin >> dash; // Read the dash
        std::cin >> s[i].character;
    }

    // Calculate the length of string s
    long long s_len = 0;
    for (int i = 0; i < m; ++i) {
        s_len += s[i].length;
    }

    // Count occurrences
    long long occurrences = 0;
    long long t_len = 0;
    for (int i = 0; i < n; ++i) {
        t_len += t[i].length;
    }

    if (s_len > t_len) {
        std::cout << 0 << std::endl;
        return 0;
    }

    std::vector<std::pair<char, long long>> expanded_t;

    // Convert t to a sequence of <char, position> pairs
    long long pos = 0;
    for (int i = 0; i < n; ++i) {
        expanded_t.push_back({t[i].character, pos});
        pos += t[i].length;
    }
    expanded_t.push_back({0, pos}); // Sentinel

    std::vector<std::pair<char, long long>> expanded_s;

    // Convert s to a sequence of <char, position> pairs
    pos = 0;
    for (int i = 0; i < m; ++i) {
        expanded_s.push_back({s[i].character, pos});
        pos += s[i].length;
    }
    expanded_s.push_back({0, pos}); // Sentinel

    // For each possible starting position
    for (long long start = 0; start <= t_len - s_len; ++start) {
        bool match = true;

        // Find which block contains the start position
        int t_idx = 0;
        while (start >= expanded_t[t_idx + 1].second) {
            t_idx++;
        }

        int s_idx = 0;
        long long t_pos = start;

        while (s_idx < m) {
            char t_char = expanded_t[t_idx].first;
            char s_char = expanded_s[s_idx].first;

            if (t_char != s_char) {
                match = false;
                break;
            }

            long long t_block_end = expanded_t[t_idx + 1].second;
            long long s_block_end = expanded_s[s_idx + 1].second - expanded_s[0].second + start;

            long long advance = std::min(t_block_end - t_pos, s_block_end - t_pos);
            t_pos += advance;

            if (t_pos >= t_block_end) {
                t_idx++;
            }

            if (t_pos >= s_block_end) {
                s_idx++;
            }
        }

        if (match) {
            occurrences++;
        }
    }

    std::cout << occurrences << std::endl;
    return 0;
}

