#include <iostream>
#include <vector>
#include <string>
#include <sstream>

using namespace std;

struct Block {
    long long len;
    char c;
};

int main() {
    int n, m;
    cin >> n >> m;

    vector<Block> t_blocks(n);
    vector<Block> s_blocks(m);

    // Read compressed string t
    for (int i = 0; i < n; i++) {
        string block;
        cin >> block;
        size_t pos = block.find('-');
        t_blocks[i].len = stoll(block.substr(0, pos));
        t_blocks[i].c = block[pos + 1];
    }

    // Read compressed string s
    for (int i = 0; i < m; i++) {
        string block;
        cin >> block;
        size_t pos = block.find('-');
        s_blocks[i].len = stoll(block.substr(0, pos));
        s_blocks[i].c = block[pos + 1];
    }

    // Decompress s_blocks into a flat vector for easier matching
    vector<pair<long long, char>> s_flat;
    for (auto& block : s_blocks) {
        if (!s_flat.empty() && s_flat.back().second == block.c) {
            s_flat.back().first += block.len;
        } else {
            s_flat.push_back({block.len, block.c});
        }
    }
    m = s_flat.size();

    // Calculate total length of s
    long long s_len = 0;
    for (auto& block : s_flat) {
        s_len += block.first;
    }

    // Calculate total occurrences
    long long total_occurrences = 0;

    // Move through t_blocks to find all possible starting positions
    vector<pair<long long, char>> t_window;
    long long cur_len = 0;

    int t_idx = 0;
    long long pos_in_block = 0;

    while (t_idx < n) {
        // Build initial window
        while (cur_len < s_len && t_idx < n) {
            long long remaining = t_blocks[t_idx].len - pos_in_block;
            if (cur_len + remaining <= s_len) {
                // Add the entire remaining part of the current block
                if (!t_window.empty() && t_window.back().second == t_blocks[t_idx].c) {
                    t_window.back().first += remaining;
                } else {
                    t_window.push_back({remaining, t_blocks[t_idx].c});
                }
                cur_len += remaining;
                t_idx++;
                pos_in_block = 0;
            } else {
                // Add only part of the current block
                if (!t_window.empty() && t_window.back().second == t_blocks[t_idx].c) {
                    t_window.back().first += (s_len - cur_len);
                } else {
                    t_window.push_back({s_len - cur_len, t_blocks[t_idx].c});
                }
                pos_in_block += (s_len - cur_len);
                cur_len = s_len;
            }
        }

        // Check if the current window matches s
        if (cur_len == s_len) {
            if (t_window.size() == s_flat.size()) {
                bool match = true;
                for (size_t i = 0; i < s_flat.size(); i++) {
                    if (t_window[i].first != s_flat[i].first || t_window[i].second != s_flat[i].second) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    total_occurrences++;
                }
            }
        }

        // Slide the window by removing the first character
        if (t_idx == n) break;

        // Remove the first character from the window
        if (t_window[0].first > 1) {
            t_window[0].first--;
            cur_len--;
        } else {
            cur_len -= t_window[0].first;
            t_window.erase(t_window.begin());
        }

        // Add the next character from t
        while (cur_len < s_len && t_idx < n) {
            if (!t_window.empty() && t_window.back().second == t_blocks[t_idx].c) {
                long long to_add = min(t_blocks[t_idx].len - pos_in_block, s_len - cur_len);
                t_window.back().first += to_add;
                cur_len += to_add;
                pos_in_block += to_add;
                if (pos_in_block == t_blocks[t_idx].len) {
                    t_idx++;
                    pos_in_block = 0;
                }
            } else {
                long long to_add = min(t_blocks[t_idx].len - pos_in_block, s_len - cur_len);
                t_window.push_back({to_add, t_blocks[t_idx].c});
                cur_len += to_add;
                pos_in_block += to_add;
                if (pos_in_block == t_blocks[t_idx].len) {
                    t_idx++;
                    pos_in_block = 0;
                }
            }
        }
    }

    cout << total_occurrences << endl;

    return 0;
}

