    long long position = 0;

    for (const auto& block : blocks) {
        long long blockEnd = position + block.length;

        // Skip blocks that end before our starting position
        if (blockEnd <= start) {
            position = blockEnd;
            continue;
        }

        // Process the part of the block that's in our range
        long long blockStart = std::max(position, start);
        long long blockContribution = std::min(blockEnd, start + length) - blockStart;

        if (blockContribution > 0) {
            result.append(blockContribution, block.character);
        }

        position = blockEnd;

        // If we've collected enough characters, break
        if (result.length() >= length) {
            break;
        }
    }

    return result;
}

long long solve(const std::vector<Block>& t_blocks, const std::vector<Block>& s_blocks) {
    // Calculate total lengths
    long long t_length = 0;
    for (const auto& block : t_blocks) {
        t_length += block.length;
    }

    long long s_length = 0;
    for (const auto& block : s_blocks) {
        s_length += block.length;
    }

    if (s_length > t_length) {
        return 0;
    }

    // Generate the pattern string
    std::string pattern;
    for (const auto& block : s_blocks) {
        pattern.append(block.length, block.character);
    }

    // Count occurrences
    long long count = 0;
    for (long long i = 0; i <= t_length - s_length; ++i) {
        std::string substring = expandString(t_blocks, i, s_length);
        if (substring == pattern) {
            count++;
        }
    }

    return count;
}

