        t_expanded.push_back({block.letter, block.length});
    }

    vector<pair<char, long long>> s_expanded;
    for (const auto& block : s_blocks) {
        s_expanded.push_back({block.letter, block.length});
    }

    // Calculate pattern length
    long long pattern_length = 0;
    for (const auto& block : s_blocks) {
        pattern_length += block.length;
    }

    // Text length
    long long text_length = 0;
    for (const auto& block : t_blocks) {
        text_length += block.length;
    }

    if (pattern_length > text_length) return 0;

    // Count occurrences
    long long occurrences = 0;

    int t_idx = 0;
    long long t_pos = 0;
    long long t_remaining = t_expanded[t_idx].second;

    for (long long start = 0; start <= text_length - pattern_length; ++start) {
        bool match = true;

        // Position in the text for current occurrence checking
