        // Move to the next position in the text
        t_remaining--;
        if (t_remaining == 0) {
            t_idx++;
            if (t_idx < t_expanded.size()) {
                t_remaining = t_expanded[t_idx].second;
            }
        }
        t_pos++;
    }

