bool solve(const std::vector<char>& ops, int n, std::vector<int>& values) {
    int num_questions = ops.size() + 1;

    // Initialize all values to 1
    values.resize(num_questions, 1);

    // Calculate initial sum
    int sum = 0;
    for (int i = 0; i < num_questions; i++) {
        if (i == 0 || ops[i-1] == '+') {
            sum += values[i];
        } else {
            sum -= values[i];
        }
    }

    // Count positive and negative terms
    int pos_terms = 1; // First term is always positive
    int neg_terms = 0;
    for (int i = 0; i < ops.size(); i++) {
        if (ops[i] == '+') pos_terms++;
        else neg_terms++;
    }

    // Adjust values
    if (sum < n) {
        int diff = n - sum;
        if (pos_terms == 0) return false;
        int add_each = diff / pos_terms;
        int remainder = diff % pos_terms;

        int pos_idx = 0;
        for (int i = 0; i < num_questions; i++) {
            if (i == 0 || ops[i-1] == '+') {
                values[i] += add_each;
                if (pos_idx < remainder) {
                    values[i]++;
                    pos_idx++;
                }
            }
        }
    } else if (sum > n) {
        int diff = sum - n;
        if (neg_terms == 0) return false;
        int add_each = diff / neg_terms;
        int remainder = diff % neg_terms;

        int neg_idx = 0;
        for (int i = 0; i < num_questions; i++) {
            if (i > 0 && ops[i-1] == '-') {
                values[i] += add_each;
                if (neg_idx < remainder) {
                    values[i]++;
                    neg_idx++;
                }
            }
        }
    }

    // Final check
    sum = 0;
    for (int i = 0; i < num_questions; i++) {
        if (i == 0 || ops[i-1] == '+') {
            sum += values[i];
        } else {
            sum -= values[i];
        }
    }

    return sum == n;
}

