            long long batch = std::min(k, min_count * max_count);

            // Each poor person gets batch / min_count
            // Each rich person gives batch / max_count
            coins[0] += batch / min_count;
            coins[n-1] -= batch / max_count;

            k -= batch;

            // Re-sort to find new min and max
            std::sort(coins.begin(), coins.end());
        }
    }

    // Find final min and max
    std::sort(coins.begin(), coins.end());

    std::cout << coins[n-1] - coins[0] << std::endl;

    return 0;
}

