int main() {
    int n;
    cin >> n;

    vector<int> a(n-1);
    for (int i = 0; i < n-1; ++i) {
        cin >> a[i];
    }

    long long total_sum = 0;

    vector<vector<pair<int, int>>> graph(n+1);

    // Build the graph
    for (int i = 1; i < n; ++i) {
        for (int j = i+1; j <= a[i-1]; ++j) {
            graph[i].push_back({j, 1});
        }
    }

    // For each starting station
    for (int start = 1; start < n; ++start) {
        vector<int> dist(n+1, 1e9);
        dist[start] = 0;

        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        pq.push({0, start});

        while (!pq.empty()) {
            int d = pq.top().first;
            int u = pq.top().second;
            pq.pop();

            if (d > dist[u]) continue;

            for (auto& edge : graph[u]) {
                int v = edge.first;
                int w = edge.second;

                if (dist[v] > dist[u] + w) {
                    dist[v] = dist[u] + w;
                    pq.push({dist[v], v});
                }
            }
        }

        for (int end = start + 1; end <= n; ++end) {
            total_sum += dist[end];
        }
    }

    cout << total_sum << endl;

