int main() {
    int n;
    cin >> n;

    vector<int> a(n - 1);
    for (int i = 0; i < n - 1; ++i) {
        cin >> a[i];
    }

    // dp[j] represents the minimum number of tickets needed to reach station j from any station
    vector<long long> dp(n + 1, 0);

    long long total = 0;

    for (int i = n - 2; i >= 0; --i) {
        // Update dp for all stations reachable from station i
        vector<long long> new_dp = dp;

        for (int j = i + 1; j <= a[i]; ++j) {
            new_dp[j] = 1;  // If directly reachable, it takes 1 ticket
        }

        for (int j = i + 1; j < n; ++j) {
            if (new_dp[j] > 0) {
                for (int k = j + 1; k <= min(a[j], n); ++k) {
                    if (new_dp[k] == 0 || new_dp[k] > new_dp[j] + 1) {
                        new_dp[k] = new_dp[j] + 1;
                    }
                }
            }
        }

        // Add the dp values to the total
        for (int j = i + 1; j < n; ++j) {
            total += new_dp[j];
        }

        dp = new_dp;
    }

    cout << total << endl;

    return 0;
}

