#include <vector>
#include <unordered_map>
#include <cmath>

using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> balances(n);
    for (int i = 0; i < n; i++) {
        cin >> balances[i];
    }

    // Edge case: if n = 1, balance must already be 0
    if (n == 1) {
        cout << 0 << endl;
        return 0;
    }

    // Calculate prefix sums
    vector<long long> prefixSum(n);
    prefixSum[0] = balances[0];
    for (int i = 1; i < n; i++) {
        prefixSum[i] = prefixSum[i-1] + balances[i];
    }

    // Count frequency of each prefix sum
    unordered_map<long long, int> freq;
    int maxFreq = 0;

    for (int i = 0; i < n; i++) {
        freq[prefixSum[i]]++;
        maxFreq = max(maxFreq, freq[prefixSum[i]]);
    }

    // Also consider 0 as a possible prefix sum (no operations needed)
    freq[0]++;
    maxFreq = max(maxFreq, freq[0]);

    // Result is n - maxFreq
    cout << n - maxFreq << endl;

    return 0;
}

