#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;

    std::vector<int> a(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }

    // Find positions of 1 and n
    int pos1 = std::find(a.begin(), a.end(), 1) - a.begin();
    int posn = std::find(a.begin(), a.end(), n) - a.begin();

    // Initial distance
    int initial_dist = std::abs(pos1 - posn);

    int max_dist = initial_dist;

    // Try all possible swaps and find the maximum distance
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            std::vector<int> temp = a;
            std::swap(temp[i], temp[j]);

            int new_pos1, new_posn;

            // Find new positions after swap
            if (temp[i] == 1) new_pos1 = i;
            else if (temp[j] == 1) new_pos1 = j;
            else new_pos1 = pos1;

            if (temp[i] == n) new_posn = i;
            else if (temp[j] == n) new_posn = j;
            else new_posn = posn;

            max_dist = std::max(max_dist, std::abs(new_pos1 - new_posn));
        }
    }

    std::cout << max_dist << std::endl;

    return 0;
}

