int main() {
    int n;
    std::cin >> n;

    std::vector<int> a(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }

    // Find positions of min (1) and max (n) elements
    int minPos = -1, maxPos = -1;
    for (int i = 0; i < n; i++) {
        if (a[i] == 1) minPos = i;
        if (a[i] == n) maxPos = i;
    }

    // Current distance
    int currentDist = std::abs(maxPos - minPos);

    // Try all possible swaps and find the maximum distance
    int maxDist = currentDist;

    // Try moving the min element (1)
    for (int i = 0; i < n; i++) {
        if (i == minPos) continue; // Skip the current position

        std::vector<int> temp = a;
        std::swap(temp[minPos], temp[i]);

        // Find new positions
        int newMinPos = i;
        int newMaxPos = (i == maxPos) ? minPos : maxPos;

        maxDist = std::max(maxDist, std::abs(newMaxPos - newMinPos));
    }

    // Try moving the max element (n)
    for (int i = 0; i < n; i++) {
        if (i == maxPos) continue; // Skip the current position

        std::vector<int> temp = a;
        std::swap(temp[maxPos], temp[i]);

        // Find new positions
        int newMinPos = (i == minPos) ? maxPos : minPos;
        int newMaxPos = i;

        maxDist = std::max(maxDist, std::abs(newMaxPos - newMinPos));
    }

    // Try all other swaps
    if (maxDist < n - 1) {
        // Try to move min to position 0 and max to position n-1
        maxDist = std::max(maxDist, n - 1);
    }

    std::cout << maxDist << std::endl;

    return 0;
}

