        long long blocks = 0;
        long long remainingVolume = volume;
        long long side = 1;

        // Find largest possible cube that fits
        while (true) {
            long long nextCube = (side + 1) * (side + 1) * (side + 1);
            if (nextCube <= remainingVolume) {
                side++;
            } else {
                break;
            }
        }

        // Add blocks greedily from largest to smallest
        while (side > 0) {
            long long cubeVolume = side * side * side;
            if (cubeVolume <= remainingVolume) {
                long long cubesCanAdd = remainingVolume / cubeVolume;
                blocks += cubesCanAdd;
                remainingVolume -= cubesCanAdd * cubeVolume;
            }
            side--;
        }

        return blocks;
    };

    while (left <= right) {
        long long mid = left + (right - left) / 2;

        // Find the maximum volume that can be constructed with mid blocks
        long long low = 1, high = m;
        long long bestVol = 0;

        while (low <= high) {
            long long vol = low + (high - low) / 2;
            long long blocks = countBlocks(vol);

            if (blocks >= mid) {
                bestVol = vol;
                low = vol + 1;
            } else {
                high = vol - 1;
            }
        }

        if (bestVol > 0 && bestVol <= m) {
            long long blocks = countBlocks(bestVol);
            if (blocks >= maxBlocks) {
                maxBlocks = blocks;
                maxVolume = bestVol;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        } else {
