        long long vol = X;
        long long blocks = 0;

        // Greedily build the tower
        while (vol > 0) {
            // Find the largest cube that fits in the remaining volume
            long long side = cbrt(vol);
            if (side == 0) break;

            long long cubeVolume = side * side * side;
            long long count = vol / cubeVolume;
            blocks += count;
            vol -= count * cubeVolume;
        }

        if (blocks > maxBlocks) {
            maxBlocks = blocks;
            bestX = X;
        }
    }

    return {maxBlocks, bestX};
}

