bool isBipartite(vector<vector<int>>& graph, vector<int>& color, int n) {
    fill(color.begin(), color.end(), -1);
    for (int start = 0; start < n; start++) {
        if (color[start] == -1) {
            color[start] = 0;
            queue<int> q;
            q.push(start);

            while (!q.empty()) {
                int u = q.front();
                q.pop();

                for (int v : graph[u]) {
                    if (color[v] == -1) {
                        color[v] = 1 - color[u];
                        q.push(v);
                    } else if (color[v] == color[u]) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

