#include <iostream>
#include <string>
#include <algorithm>

int main() {
    std::string n;
    std::cin >> n;

    // Check if n is 1
    if (n == "1") {
        std::cout << "11" << std::endl;
        return 0;
    }

    // Subtract 9 from n (for single digit palindromes 11, 22, ..., 99)
    bool subtract = true;
    for (int i = n.size() - 1; i >= 0; i--) {
        if (subtract) {
            if (n[i] >= '9') {
                n[i] = '0';
            } else {
                n[i]++;
                subtract = false;
            }
        }

        if (n[i] > '0') {
            n[i] = char(n[i] - 9);
            subtract = false;
        } else {
            n[i] = '1';
            subtract = true;
        }
    }

    if (subtract) {
        n = "1" + n;
    }

    // Now n represents the number of palindromes after the first 9
    // We need to find the first half of the palindrome
    std::string firstHalf;
    if (n == "1") {
        firstHalf = "10";
    } else {
        firstHalf = n;
        firstHalf = std::to_string(std::stoll(firstHalf) + 9);
    }

    // Create the palindrome by mirroring the first half
    std::string secondHalf = firstHalf;
    std::reverse(secondHalf.begin(), secondHalf.end());

    std::cout << firstHalf << secondHalf << std::endl;

    return 0;
}

