#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;

    std::vector<int> points(n);
    for (int i = 0; i < n; i++) {
        std::cin >> points[i];
    }

    std::sort(points.begin(), points.end());

    // The median minimizes the sum of absolute differences
    int median;
    if (n % 2 == 1) {
        median = points[n / 2];
    } else {
        // For even number of points, any value between the two middle elements is optimal
        // The problem asks for the leftmost optimal point
        median = points[n / 2 - 1];
    }

    std::cout << median << std::endl;

    return 0;
}

