int solve(int x, int y) {
    int count = 0;
    int a = x, b = x, c = x;

    while (std::min({a, b, c}) > y) {
        if (a >= b && a >= c) {
            a = std::max(1, std::max(b - c + 1, y));
        } else if (b >= a && b >= c) {
            b = std::max(1, std::max(a - c + 1, y));
        } else {
            c = std::max(1, std::max(a - b + 1, y));
        }
        count++;
    }

    while (a > y) { a--; count++; }
    while (b > y) { b--; count++; }
    while (c > y) { c--; count++; }

    return count;
}

