    while (num > 0) {
        int digit = num % 10;
        signature = (digit % 2 == 0 ? "0" : "1") + signature;
        num /= 10;
    }
    return signature;
}

// Check if a number matches a pattern
bool matches(const string& signature, const string& pattern) {
    if (signature.length() < pattern.length()) {
        // Pad signature with leading 0s
        string padded = string(pattern.length() - signature.length(), '0') + signature;
        return padded == pattern;
    } else if (signature.length() > pattern.length()) {
        // Check only the suffix of signature that matches pattern length
        return signature.substr(signature.length() - pattern.length()) == pattern;
    } else {
        return signature == pattern;
    }
}

