        height++;
    }

    // For a complete binary tree of height h with n leaves
    long long totalBits = 0;

    // If n is a power of 2, all codewords have the same length
    if (n == (1LL << height)) {
        totalBits = n * height;
    } else {
        // Number of nodes at max depth
