        // Number of nodes at (max depth - 1)
        long long nodesAtMaxDepthMinus1 = (1LL << height) - n;

        // Total number of bits
        totalBits = nodesAtMaxDepth * height + nodesAtMaxDepthMinus1 * (height - 1);
    }

    // Calculate cost based on frequencies of 0 and 1
    if (c0 <= c1) {
