using namespace std;

long long solve(long long n, long long c0, long long c1) {
    // For n letters, we need a complete binary tree of height h where 2^h >= n

    // Find the height needed
    long long h = 0;
    long long power = 1;
    while (power < n) {
        h++;
        power *= 2;
    }

    // For full level 0 to h-1: 
    // - Bits at each level i: 2^i
    // - Each bit appears in 2^(h-i) nodes
    long long cost = 0;

    for (long long i = 0; i < h; i++) {
        long long bits_at_level = (1LL << i);
        long long nodes_per_bit = (1LL << (h - i));

        // Choose the cheaper bit for each position
        if (c0 <= c1) {
            // Use c0 for all bits at this level if possible
            cost += bits_at_level * c0 * min(nodes_per_bit, n);
        } else {
            // Use c1 for all bits at this level if possible
            cost += bits_at_level * c1 * min(nodes_per_bit, n);
        }

        // Reduce remaining nodes for next level
        n -= nodes_per_bit;
        if (n <= 0) break;
    }

    return cost;
}

