bool isVowel(char c) {
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' || c == 'y';
}

// Count minimum possible number of syllables in a word
int countMinSyllables(const std::string& word) {
    int count = 0;
    int i = 0;

    while (i < word.length()) {
        // Find next vowel
        while (i < word.length() && !isVowel(word[i])) {
            i++;
        }

        // If found a vowel, count a syllable
        if (i < word.length()) {
            count++;
            i++;

            // Skip consecutive vowels as they must be in different syllables
            while (i < word.length() && isVowel(word[i])) {
                count++;
                i++;
            }
        }
    }

    return count;
}

int main() {
    int n;
    std::cin >> n;

    std::vector<int> pattern(n);
    for (int i = 0; i < n; i++) {
        std::cin >> pattern[i];
    }

    std::cin.ignore(); // Ignore newline after pattern input

    for (int i = 0; i < n; i++) {
        std::string line;
        std::getline(std::cin, line);

        std::istringstream iss(line);
        std::string word;
        int totalSyllables = 0;

        while (iss >> word) {
            // Count syllables in each word and add to total
            totalSyllables += countMinSyllables(word);
        }

        // If syllable count doesn't match pattern, print NO and exit
