#include <string>

using namespace std;

int main() {
    int n;
    cin >> n;
    string bumpers;
    cin >> bumpers;

    vector<bool> visited(n, false);
    vector<bool> willFall(n, false);

    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;

        vector<int> path;
        int current = i;

        while (true) {
            if (current < 0 || current >= n) {
                // Ball falls out
                for (int pos : path) {
                    willFall[pos] = true;
                    visited[pos] = true;
                }
                break;
            }

            if (visited[current]) {
                // Already determined
                if (willFall[current]) {
                    for (int pos : path) {
                        willFall[pos] = true;
                        visited[pos] = true;
                    }
                } else {
                    for (int pos : path) {
                        visited[pos] = true;
                    }
                }
                break;
            }

            if (find(path.begin(), path.end(), current) != path.end()) {
                // Found a cycle
                for (int pos : path) {
                    visited[pos] = true;
                }
                break;
            }

            path.push_back(current);

            // Move the ball
            if (bumpers[current] == '>') {
                current++;
            } else {
                current--;
            }
        }
    }

    int count = 0;
    for (int i = 0; i < n; i++) {
        if (willFall[i]) count++;
    }

    cout << count << endl;

    return 0;
}

