int minWrongWorkers(int n, int s, vector<int>& reports) {
    vector<vector<vector<int>>> dp(n + 1, vector<vector<int>>(n, vector<int>(n, INT_MAX)));

    // dp[i][j][k] = minimum number of wrong workers for first i workers,
    // where worker j is the chief, and k is the number of people reporting to the chief

    // Base case
    for (int k = 0; k < n; ++k) {
        dp[1][0][k] = (reports[0] != k);
    }

    for (int i = 2; i <= n; ++i) {
        for (int j = 0; j < i - 1; ++j) { // j is superior of i-1
            for (int k = 0; k < i - 1; ++k) { // k is number of people reporting to the chief
                if (dp[i-1][j][k] == INT_MAX) continue;

                // Worker i-1 reports to worker j
                int depth = 1; // depth from i-1 to chief
                int curr = j;
                while (curr != s - 1) {
                    curr = (curr == -1) ? -1 : curr;
                    depth++;
                }

                int wrong = dp[i-1][j][k] + (reports[i-1] != depth);
                dp[i][i-1][k + (j == s - 1 ? 1 : 0)] = min(dp[i][i-1][k + (j == s - 1 ? 1 : 0)], wrong);
            }
        }

        // Worker i-1 reports directly to the chief
        for (int k = 0; k < i - 1; ++k) {
            if (dp[i-1][s-1][k] == INT_MAX) continue;
            int wrong = dp[i-1][s-1][k] + (reports[i-1] != 1);
            dp[i][i-1][k+1] = min(dp[i][i-1][k+1], wrong);
        }
    }

    // Find the minimum number of wrong workers
    int result = INT_MAX;
    for (int j = 0; j < n; ++j) {
