    int currentPos = -1;  // Grasshopper starts just before the first character
    int maxJump = 0;

    while (currentPos < n) {
        int nextPos = currentPos;

        // Find the farthest vowel within current jump ability
        for (int i = 1; i <= maxJump || maxJump == 0; i++) {
            int newPos = currentPos + i;

            // If we've reached the end of the string
            if (newPos >= n) {
                nextPos = n;
                break;
            }

            // If we found a vowel
            if (isVowel(s[newPos])) {
                nextPos = newPos;
            }
        }

        // If we couldn't make progress, increase jump ability
        if (nextPos == currentPos) {
            maxJump++;
        } else {
            currentPos = nextPos;
        }
    }

    std::cout << maxJump << std::endl;

    return 0;
}

