#include <iostream>
#include <vector>
#include <cstring>
using namespace std;

const int MAXN = 105;
int n;
int crush[MAXN];
bool visited[MAXN];
int cycle_length[MAXN];
int path_length[MAXN][MAXN];

void dfs(int node, int start, int len) {
    visited[node] = true;

    int next = crush[node];
    if (!visited[next]) {
        dfs(next, start, len + 1);
    } else if (next == start) {
        cycle_length[start] = len + 1;
    }
}

void computePathLengths() {
    for (int i = 1; i <= n; i++) {
        memset(visited, 0, sizeof(visited));
        int node = i;
        int len = 0;

        while (!visited[node]) {
            visited[node] = true;
            path_length[i][node] = len;
            node = crush[node];
            len++;
        }

        // Find the start of the cycle
        memset(visited, 0, sizeof(visited));
        dfs(i, i, 0);
    }
}

bool check(int t) {
    for (int i = 1; i <= n; i++) {
        int end_node = i;
        for (int j = 1; j <= t; j++) {
            end_node = crush[end_node];
        }

        int reverse_end = end_node;
        for (int j = 1; j <= t; j++) {
            reverse_end = crush[reverse_end];
        }

        if (reverse_end != i) {
            return false;
        }
    }
    return true;
}

int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

int lcm(int a, int b) {
    return a / gcd(a, b) * b;
}

int main() {
    cin >> n;
    for (int i = 1; i <= n; i++) {
        cin >> crush[i];
    }

    computePathLengths();

    // Calculate LCM of all cycle lengths
    int result = 1;
    for (int i = 1; i <= n; i++) {
        if (cycle_length[i] > 0) {
            result = lcm(result, cycle_length[i]);
        }
    }

    // Check if the condition is satisfied
    if (check(result)) {
        cout << result << endl;
    } else {
        cout << -1 << endl;
    }

    return 0;
}

