#include <algorithm>

using namespace std;

struct Task {
    int time, servers_needed, duration, index;
};

struct ServerBusy {
    int id, free_time;

    bool operator<(const ServerBusy& other) const {
        if (free_time == other.free_time)
            return id > other.id;
        return free_time > other.free_time;
    }
};

int main() {
    int n, q;
    cin >> n >> q;

    vector<Task> tasks(q);
    for (int i = 0; i < q; i++) {
        cin >> tasks[i].time >> tasks[i].servers_needed >> tasks[i].duration;
        tasks[i].index = i;
    }

    vector<int> results(q, -1);
    priority_queue<ServerBusy> busy_servers;

    // Start all servers as free at time 0
    for (int i = 1; i <= n; i++) {
        busy_servers.push({i, 0});
    }

    for (const Task& task : tasks) {
        int current_time = task.time;
        vector<int> available_servers;

        // Free servers that have finished their tasks by current time
        while (!busy_servers.empty() && busy_servers.top().free_time <= current_time) {
            available_servers.push_back(busy_servers.top().id);
            busy_servers.pop();
        }

        // Sort available servers by ID
        sort(available_servers.begin(), available_servers.end());

        if (available_servers.size() >= task.servers_needed) {
            int sum_of_ids = 0;

            // Use the servers with smallest IDs
            for (int i = 0; i < task.servers_needed; i++) {
                sum_of_ids += available_servers[i];
                busy_servers.push({available_servers[i], current_time + task.duration});
            }

            // Put back the unused servers
            for (int i = task.servers_needed; i < available_servers.size(); i++) {
                busy_servers.push({available_servers[i], 0});
            }

            results[task.index] = sum_of_ids;
        } else {
            // Not enough servers, put them back
            for (int id : available_servers) {
                busy_servers.push({id, 0});
            }
        }
    }

    // Output results
    for (int result : results) {
        cout << result << endl;
    }

