    int id;
    int busyUntil;

    bool operator<(const Server& other) const {
        // When comparing servers, we prioritize by busyUntil time first,
        // and if they have the same busyUntil time, we prioritize by id
        if (busyUntil == other.busyUntil) {
            return id > other.id;  // Min-heap should give smallest id first
        }
        return busyUntil > other.busyUntil;  // Min-heap by busyUntil
    }
};

