    int n, q;
    cin >> n >> q;

    vector<Task> tasks(q);
    for (int i = 0; i < q; i++) {
        cin >> tasks[i].time >> tasks[i].serversNeeded >> tasks[i].duration;
        tasks[i].index = i;
    }

