    priority_queue<Server> servers;

    // Initialize all servers as free
    for (int i = 1; i <= n; i++) {
        servers.push({i, 0});
    }

    for (const Task& task : tasks) {
        int time = task.time;
        int serversNeeded = task.serversNeeded;
        int duration = task.duration;
        int taskIndex = task.index;

        // We'll collect servers that are free at this time
