    int time;
    int servers_needed;
    int duration;
    int index;
};

struct ServerEvent {
    int time;
    int server_id;

    bool operator>(const ServerEvent& other) const {
        return time > other.time;
    }
};

int main() {
    int n, q;
    cin >> n >> q;

    vector<Task> tasks(q);
    for (int i = 0; i < q; i++) {
        cin >> tasks[i].time >> tasks[i].servers_needed >> tasks[i].duration;
        tasks[i].index = i;
    }

    vector<int> results(q, -1);
    priority_queue<ServerEvent, vector<ServerEvent>, greater<ServerEvent>> busy_servers;
    vector<bool> is_server_busy(n + 1, false);

    for (const Task& task : tasks) {
        int current_time = task.time;

        // Free up servers that have finished their tasks
        while (!busy_servers.empty() && busy_servers.top().time <= current_time) {
            int server_id = busy_servers.top().server_id;
            busy_servers.pop();
            is_server_busy[server_id] = false;
        }

        // Count available servers
        int available_servers = 0;
        for (int i = 1; i <= n; i++) {
            if (!is_server_busy[i]) {
                available_servers++;
            }
        }

        // Check if we have enough servers for this task
        if (available_servers >= task.servers_needed) {
            int sum_of_ids = 0;
            int assigned = 0;

            // Assign servers with smallest IDs
            for (int i = 1; i <= n && assigned < task.servers_needed; i++) {
                if (!is_server_busy[i]) {
                    is_server_busy[i] = true;
                    busy_servers.push({current_time + task.duration, i});
                    sum_of_ids += i;
                    assigned++;
                }
            }

            results[task.index] = sum_of_ids;
        }
    }

    // Output results
    for (int result : results) {
        cout << result << endl;
    }

    return 0;
}

