struct Task {
    int time, serversNeeded, duration, index;
};

int main() {
    int n, q;
    cin >> n >> q;

    vector<Task> tasks(q);
    for (int i = 0; i < q; i++) {
        cin >> tasks[i].time >> tasks[i].serversNeeded >> tasks[i].duration;
        tasks[i].index = i;
    }

    vector<int> results(q, -1);
    vector<pair<int, int>> serverBusyUntil; // pair<time, serverId>

    for (int i = 0; i < q; i++) {
        const Task& task = tasks[i];

        // Remove servers that are no longer busy
        while (!serverBusyUntil.empty() && serverBusyUntil[0].first <= task.time) {
            serverBusyUntil.erase(serverBusyUntil.begin());
        }

        // Check if we have enough free servers
        int busyServers = serverBusyUntil.size();
        if (n - busyServers < task.serversNeeded) {
            continue; // Not enough free servers, skip this task
        }

        // Get the set of busy server IDs
        set<int> busyServerIds;
        for (const auto& pair : serverBusyUntil) {
            busyServerIds.insert(pair.second);
        }

        // Find the free servers with smallest IDs
        int sum = 0;
        vector<int> usedServers;
        for (int j = 1; j <= n && usedServers.size() < task.serversNeeded; j++) {
            if (busyServerIds.find(j) == busyServerIds.end()) {
                usedServers.push_back(j);
                sum += j;
            }
        }

        // Assign servers to this task
        for (int serverId : usedServers) {
            serverBusyUntil.push_back({task.time + task.duration, serverId});
        }

        // Sort to ensure earliest finishing servers are first
        sort(serverBusyUntil.begin(), serverBusyUntil.end());

        results[task.index] = sum;
    }

    for (int result : results) {
        cout << result << endl;
    }

    return 0;
}

