    vector<vector<pair<int, bool>>> graph(2 * n);
    for (int i = 0; i < n; i++) {
        graph[i].push_back({p[i], b[i] == 1});
        graph[i + n].push_back({p[i] + (b[i] == 1 ? 0 : n), b[i] == 1});
    }

    // Check if all nodes are reachable from each starting position
    int total_changes = 0;

    for (int start = 0; start < n; start++) {
        vector<bool> visited(2 * n, false);
