    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            int count = 0;
            int current = i;

            while (!visited[current]) {
                visited[current] = true;
                current = p[current] - 1; // Convert to 0-indexed
                count++;
            }

            cycles.push_back(count);
        }
    }

