pair<bool, int> is_reachable(const vector<int>& p, const vector<int>& b, int n) {
    // Build the graph: node (i, dir) represents skewer at position i with direction dir
    vector<vector<pair<int, int>>> graph(2*n);
    for (int i = 0; i < n; i++) {
        int next_pos = p[i] - 1; // 0-indexed
        int next_dir_if_0 = 0; // No flip
        int next_dir_if_1 = 1; // Flip

        // From position i, direction 0
        graph[i].push_back({next_pos, b[i] ? next_dir_if_1 : next_dir_if_0});
        // From position i, direction 1
        graph[i + n].push_back({next_pos + (b[i] ? 0 : n), b[i] ? next_dir_if_0 : next_dir_if_1});
    }

    // BFS to find reachable nodes from the starting point (0, 0)
    vector<bool> visited(2*n, false);
    vector<int> distance(2*n, -1);
    queue<int> q;

    q.push(0); // Start from position 0, direction 0
    visited[0] = true;
    distance[0] = 0;

    while (!q.empty()) {
        int node = q.front();
        q.pop();

        for (auto [next_pos, next_dir] : graph[node]) {
