    long long remaining = k % (cycleSize * m);

    long long maxQuestions = fullCycles;

    if (remaining > 0) {
        long long rowCyclePos = (remaining - 1) / m;
        long long colPos = (remaining - 1) % m + 1;

        if (rowCyclePos < n) {
            // Check first n rows
            for (long long i = 1; i <= n; i++) {
                long long extra = (i <= rowCyclePos || (i == rowCyclePos + 1 && colPos > 0)) ? 1 : 0;
                maxQuestions = max(maxQuestions, fullCycles + extra);
