        }
    }

    // Corner rows (1 and n) appear once in a cycle
    // Middle rows (2 to n-1) appear twice in a cycle
    long long firstLastRowCount = (k / (cycleSize * m)) + (k % (cycleSize * m) > 0 ? 1 : 0);
    long long middleRowCount = 2 * (k / (cycleSize * m)) + (k % (cycleSize * m) > 0 ? 1 : 0);

    return max(firstLastRowCount, middleRowCount);
