        int len = dp[n];
        if (!best[len].empty()) {
            best[len].push_back({start, m});
        } else {
            best[len] = {{start, m}};
        }
    }

    // Find the maximum length that can be achieved
    int max_len = 0;
    for (int i = m; i >= 0; i--) {
        if (!best[i].empty()) {
