    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    vector<vector<pair<int, int>>> backtrack(n + 1, vector<pair<int, int>>(m + 1, {-1, -1}));

    int max_length = 0;
    pair<int, int> end_pos = {0, 0};

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            // Case 1: don't use a[i-1]
            dp[i][j] = dp[i-1][j];
            backtrack[i][j] = {i-1, j};

            // Case 2: a[i-1] matches b[j-1] and we use it
            if (a[i-1] == b[j-1]) {
                // We can either continue a previous match or start a new one
                if (dp[i-1][j-1] + 1 > dp[i][j]) {
                    dp[i][j] = dp[i-1][j-1] + 1;
                    backtrack[i][j] = {i-1, j-1};
                }

                // Option to start a new match
                if (1 > dp[i][j]) {
                    dp[i][j] = 1;
                    backtrack[i][j] = {-1, -1}; // Mark as start of a match
                }
            }

            if (dp[i][j] > max_length) {
                max_length = dp[i][j];
                end_pos = {i, j};
            }
