    // such that the remaining subsequence is a subsequence of a[0..i]
    vector<vector<int>> dp(n+1, vector<int>(m+1, INT_MAX/2));

    // Base case: empty b is a subsequence of any a
    for (int i = 0; i <= n; ++i) {
        dp[i][0] = 0;
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            // Don't include b[j-1]
            dp[i][j] = dp[i][j-1] + 1;

            // Include b[j-1] if it matches a[i-1]
            if (a[i-1] == b[j-1]) {
                dp[i][j] = min(dp[i][j], dp[i-1][j-1]);
            } else {
                // Try to match with previous character in a
                dp[i][j] = min(dp[i][j], dp[i-1][j]);
            }
        }
    }

    if (dp[n][m] == m) {
        // If we need to remove all characters from b
        cout << "-" << endl;
        return 0;
    }

