    std::vector<int> b(m);
    for (int i = 0; i < m; i++) {
        std::cin >> b[i];
    }

    std::vector<std::vector<std::pair<int, int>>> dp(n + 1, std::vector<std::pair<int, int>>(m + 1, {0, -1}));

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            // Copy the value from the left
            dp[i][j] = dp[i][j-1];

            // If elements match, try to extend a previous LCIS
            if (a[i-1] == b[j-1]) {
                // Find the longest LCIS that ends with a value smaller than a[i-1]
                int max_len = 0;
                int prev_idx = -1;
                for (int k = 0; k < j; k++) {
                    if (b[k] < b[j-1] && dp[i-1][k+1].first > max_len) {
                        max_len = dp[i-1][k+1].first;
                        prev_idx = k+1;
                    }
                }

                // If we can form a better LCIS by adding this element
                if (max_len + 1 > dp[i][j].first) {
                    dp[i][j] = {max_len + 1, prev_idx};
                }
            }

            // Copy if previous row has a better solution
            if (dp[i-1][j].first > dp[i][j].first) {
                dp[i][j] = dp[i-1][j];
            }
        }
    }

    // Find the length of LCIS
    int length = dp[n][m].first;
    std::cout << length << std::endl;

    // If length is 0, don't print anything else
