        return 0;
    }

    // Reconstruct the LCIS
    std::vector<int> lcis;
    int i = n, j = m;

    while (i > 0 && j > 0) {
        if (dp[i][j].first > dp[i-1][j].first && dp[i][j].first > dp[i][j-1].first && a[i-1] == b[j-1]) {
            lcis.push_back(a[i-1]);
            j = dp[i][j].second;
            i--;
        } else if (dp[i][j].first == dp[i-1][j].first) {
            i--;
        } else {
            j--;
        }
    }

    // Reverse and print the LCIS
    std::reverse(lcis.begin(), lcis.end());
    for (int val : lcis) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    return 0;
}

