#include <iostream>
#include <vector>
#include <iomanip>

using namespace std;

long long binomial_coefficient(int n, int k) {
    if (k > n) return 0;
    if (k == 0 || k == n) return 1;

    long long result = 1;
    k = min(k, n - k);

    for (int i = 1; i <= k; ++i) {
        result *= n - i + 1;
        result /= i;
    }

    return result;
}

int main() {
    int n, m, h;
    cin >> n >> m >> h;

    vector<int> students(m);
    for (int i = 0; i < m; ++i) {
        cin >> students[i];
    }

    int total_students = 0;
    for (int count : students) {
        total_students += count;
    }

    // Check if there are enough students
    if (total_students < n) {
        cout << -1 << endl;
        return 0;
    }

    // Herr Wafa is already on the team, so we need to select (n-1) more players
    int wafa_department_size = students[h-1];

    if (wafa_department_size == 0) {
        cout << -1 << endl;
        return 0;
    }

    // Herr Wafa is one of the students in his department
    wafa_department_size--;

    // Total students excluding Herr Wafa
    total_students--;

    // Calculate probability of having at least one teammate from Herr Wafa's department
    if (wafa_department_size == 0) {
        // No other students in Herr Wafa's department
        cout << 0 << endl;
        return 0;
    }

    // Calculate probability
    // P(at least one teammate from same department) = 1 - P(no teammate from same department)
    // P(no teammate from same department) = C(total_students - wafa_department_size, n-1) / C(total_students, n-1)

    long long ways_to_select_none = binomial_coefficient(total_students - wafa_department_size, n - 1);
    long long total_ways = binomial_coefficient(total_students, n - 1);

    double probability = 1.0 - (double)ways_to_select_none / total_ways;

    cout << fixed << setprecision(6) << probability << endl;

    return 0;
}

