#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <utility>

using namespace std;

// Bipartite graph matching using Ford-Fulkerson algorithm
bool bfs(vector<vector<int>>& graph, int source, int sink, vector<int>& parent) {
    int n = graph.size();
    vector<bool> visited(n, false);
    queue<int> q;

    q.push(source);
    visited[source] = true;
    parent[source] = -1;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v = 0; v < n; ++v) {
            if (!visited[v] && graph[u][v] > 0) {
                q.push(v);
                parent[v] = u;
                visited[v] = true;
            }
        }
    }

    return visited[sink];
}

int maxFlow(vector<vector<int>>& graph, int source, int sink) {
    int n = graph.size();
    vector<int> parent(n);
    int max_flow = 0;

    while (bfs(graph, source, sink, parent)) {
        int path_flow = INT_MAX;
        for (int v = sink; v != source; v = parent[v]) {
            int u = parent[v];
            path_flow = min(path_flow, graph[u][v]);
        }

        for (int v = sink; v != source; v = parent[v]) {
            int u = parent[v];
            graph[u][v] -= path_flow;
            graph[v][u] += path_flow;
        }

        max_flow += path_flow;
    }

    return max_flow;
}

int main() {
    int n, m;
    cin >> n >> m;

    vector<string> grid(n);
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
    }

    vector<pair<int, int>> wolves, pigs;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'W') {
                wolves.push_back({i, j});
            } else if (grid[i][j] == 'P') {
                pigs.push_back({i, j});
            }
        }
    }

    // Construct bipartite graph: wolves -> pigs
    int num_wolves = wolves.size();
    int num_pigs = pigs.size();

    // +2 for source and sink nodes
    int num_nodes = num_wolves + num_pigs + 2;
    int source = 0;
    int sink = num_nodes - 1;

    vector<vector<int>> graph(num_nodes, vector<int>(num_nodes, 0));

    // Connect source to wolves
    for (int i = 0; i < num_wolves; ++i) {
        graph[source][i + 1] = 1;
    }

    // Connect pigs to sink
    for (int i = 0; i < num_pigs; ++i) {
        graph[num_wolves + i + 1][sink] = 1;
    }

    // Connect wolves to pigs if adjacent
    for (int i = 0; i < num_wolves; ++i) {
        for (int j = 0; j < num_pigs; ++j) {
            int dx = abs(wolves[i].first - pigs[j].first);
            int dy = abs(wolves[i].second - pigs[j].second);
            if (dx + dy == 1) {  // Adjacent
                graph[i + 1][num_wolves + j + 1] = 1;
            }
        }
    }

    int result = maxFlow(graph, source, sink);
    cout << result << endl;

    return 0;
}

