        cin >> proficiency[i];
    }

    int q;
    cin >> q;

    vector<bool> used(n, false);
    for (int i = 0; i < q; i++) {
        int theorems_per_card = n / k;
        vector<int> card(theorems_per_card);

        for (int j = 0; j < theorems_per_card; j++) {
            cin >> card[j];
            used[card[j] - 1] = true;
        }
    }

    vector<int> unused;
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            unused.push_back(proficiency[i]);
        }
    }

    sort(unused.begin(), unused.end());

    int theorems_per_card = n / k;
    int cards_left = k - q;

    double min_proficiency = 0.0;
    double max_proficiency = 0.0;

    if (cards_left == 1) {
        min_proficiency = accumulate(unused.begin(), unused.end(), 0.0) / unused.size();
        max_proficiency = min_proficiency;
    } else {
        int total_theorems_left = unused.size();

        // Minimum proficiency: put best theorems in other cards, leaving worst ones
        int worst_card_size = total_theorems_left - (cards_left - 1) * theorems_per_card;
        double worst_card_sum = 0.0;
        for (int i = 0; i < worst_card_size; i++) {
            worst_card_sum += unused[i];
        }
        min_proficiency = worst_card_sum / worst_card_size;

        // Maximum proficiency: put worst theorems in other cards, leaving best ones
        int best_card_size = total_theorems_left - (cards_left - 1) * theorems_per_card;
        double best_card_sum = 0.0;
        for (int i = total_theorems_left - best_card_size; i < total_theorems_left; i++) {
            best_card_sum += unused[i];
        }
        max_proficiency = best_card_sum / best_card_size;
    }

    cout << fixed << setprecision(10) << min_proficiency << " " << max_proficiency << endl;

    return 0;
}

