#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string xml;
    std::cin >> xml;

    int indent = 0;
    int idx = 0;
    while (idx < xml.size()) {
        if (xml[idx] == '<') {
            // Check if it's a closing tag
            if (xml[idx + 1] == '/') {
                indent -= 2;
                for (int i = 0; i < indent; ++i) {
                    std::cout << " ";
                }

                // Find where this tag ends
                int end = idx;
                while (end < xml.size() && xml[end] != '>') end++;
                std::cout << xml.substr(idx, end - idx + 1);
                idx = end + 1;
            } else {
                // It's an opening tag
                for (int i = 0; i < indent; ++i) {
                    std::cout << " ";
                }

                // Find where this tag ends
                int end = idx;
                while (end < xml.size() && xml[end] != '>') end++;
                std::cout << xml.substr(idx, end - idx + 1);
                indent += 2;
                idx = end + 1;
            }
        }
    }

    return 0;
}

