#include <vector>

int main() {
    std::string xml;
    std::cin >> xml;

    std::string result;
    int nestLevel = 0;
    bool inTag = false;
    std::string currentTag;

    for (char c : xml) {
        if (c == '<') {
            inTag = true;
            currentTag = "<";
        } else if (c == '>') {
            inTag = false;
            currentTag += ">";

            if (currentTag[1] == '/') {
                // Closing tag
                nestLevel--;
                result += std::string(2 * nestLevel, ' ') + currentTag;
            } else {
                // Opening tag
                result += std::string(2 * nestLevel, ' ') + currentTag;
                nestLevel++;
            }
        } else {
            currentTag += c;
        }
    }

    size_t pos = 0;
    while ((pos = result.find("><", pos)) != std::string::npos) {
        result.insert(pos + 1, "\n");
        pos += 2;
    }

    std::cout << result << std::endl;

    return 0;
}

