    std::unordered_map<int, int> adjacentCount;

    for (auto it = freq.begin(); it != freq.end(); ++it) {
        int num = it->first;
        adjacentCount[num] = freq[num - 1] + freq[num + 1];
    }

    // Each number should have exactly the same number of neighbors as its frequency
    for (auto it = freq.begin(); it != freq.end(); ++it) {
        int num = it->first;
        int count = it->second;

        if (count > adjacentCount[num]) {
            possible = false;
            break;
        }
    }

