    // or exactly two numbers must have odd frequency
    int oddCount = 0;
    for (auto it = freq.begin(); it != freq.end(); ++it) {
        if (it->second > adjacentCount[it->first]) {
            possible = false;
            break;
        }
        if (adjacentCount[it->first] > it->second) {
            int diff = adjacentCount[it->first] - it->second;
            if (diff % 2 == 1) {
                oddCount++;
            }
        }
    }

    if (oddCount > 0 && oddCount != 2) {
        possible = false;
    }

