#include <unordered_map>
#include <algorithm>

using namespace std;

bool canFormCircle(vector<int>& nums) {
    if (nums.size() < 3) return false;

    unordered_map<int, int> freq;
    for (int num : nums) {
        freq[num]++;
    }

    // Count numbers with odd frequency
    int odd_count = 0;
    for (auto& p : freq) {
        if (p.second % 2 == 1) {
            odd_count++;
        }
    }

    // For each number, check if it has neighbors
    for (auto& p : freq) {
        int num = p.first;
        int count = p.second;

        int neighbors_count = 0;
        neighbors_count += freq[num - 1];
        neighbors_count += freq[num + 1];

        // Each number needs at least as many neighbors as its count
        if (neighbors_count < count) {
            return false;
        }
    }

    // Check if the circle is valid
    return odd_count == 0;
}

