const int MOD = 1000000007;

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    if (k == 0) {
        cout << 1 << endl;
        return 0;
    }

    // dp[i][j][p] = Number of ways to place p rectangles inside an i×j rectangle
    vector<vector<vector<int>>> dp(n + 1, vector<vector<int>>(m + 1, vector<int>(k + 1, 0)));

    // Base case: 1 way to place 0 rectangles in any size
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            dp[i][j][0] = 1;
        }
    }

    for (int p = 1; p <= k; p++) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                // Try all possible inner rectangles of size w×h
                for (int w = 1; w < i; w++) {
                    for (int h = 1; h < j; h++) {
                        // Count number of ways to place a w×h rectangle
                        // There are (i-w+1)*(j-h+1) positions to place the top-left corner
                        long long ways = (long long)(i - w + 1) * (j - h + 1) % MOD;
                        // Multiply by number of ways to place p-1 rectangles inside the w×h rectangle
                        ways = (ways * dp[w][h][p - 1]) % MOD;
                        dp[i][j][p] = (dp[i][j][p] + ways) % MOD;
                    }
                }
            }
        }
    }

    cout << dp[n][m][k] << endl;

    return 0;
}

