    long long totalSum = 0;
    for (long long b = 2; b < A; b++) {
        totalSum += digitSum(A, b);
    }

    // Number of bases is (A-1) - 2 + 1 = A-2
    long long denominator = A - 2;

    // Find GCD to reduce the fraction
    long long divisor = gcd(totalSum, denominator);

    // Output the irreducible fraction
    cout << totalSum / divisor << "/" << denominator / divisor << endl;

