            string newCards = "";
            for (int j = 0; j < n; j++) {
                if (j != i) newCards += cards[j];
            }

            // Compute new position after removal
            int newPos = pos;
            if (i < pos) newPos--;

            // If pos is the card being removed, this position won't be in the final outcome
            if (i == pos) {
                visited[i] = false;
                continue;
            }

            char result = finalDigit(newCards, newPos, !mashasTurn, memo);
            best = min(best, result);

            visited[i] = false;
        }
        memo[n][pos][mashasTurn] = best;
        return best;
    } else {
        // Petya wants to maximize
