                string currentCards = cards;
                bool mashasTurn = true; // Masha moves first

                // Play the game optimally
                while (currentCards.size() > 2) {
                    int bestMove = -1;
                    char bestValue = mashasTurn ? '1' : '0';

                    for (int k = 0; k < currentCards.size(); k++) {
