using namespace std;

// Minimax function to determine the best outcome
pair<int, int> minimax(vector<char>& cards, int alpha, int beta, bool isMin) {
    int n = cards.size();
    if (n == 2) {
        int value = (cards[0] - '0') * 2 + (cards[1] - '0');
        return {value, -1}; // value, best move
    }

    int bestMove = -1;
    if (isMin) { // Masha's move (minimizing)
        int bestVal = beta;
        for (int i = 0; i < n; i++) {
            vector<char> newCards = cards;
            newCards.erase(newCards.begin() + i);
            int val = minimax(newCards, alpha, bestVal, !isMin).first;
            if (val < bestVal) {
                bestVal = val;
                bestMove = i;
                if (bestVal <= alpha) break; // Alpha-beta pruning
            }
        }
        return {bestVal, bestMove};
    } else { // Petya's move (maximizing)
        int bestVal = alpha;
        for (int i = 0; i < n; i++) {
            vector<char> newCards = cards;
            newCards.erase(newCards.begin() + i);
            int val = minimax(newCards, bestVal, beta, !isMin).first;
            if (val > bestVal) {
                bestVal = val;
                bestMove = i;
                if (bestVal >= beta) break; // Alpha-beta pruning
            }
        }
        return {bestVal, bestMove};
    }
}

// Generate all possible configurations from ? cards
void generateConfigurations(const string& input, int index, vector<char>& current, vector<vector<char>>& allConfigs) {
    if (index == input.size()) {
        allConfigs.push_back(current);
        return;
    }

    if (input[index] == '?') {
        // Try with '0'
        current[index] = '0';
        generateConfigurations(input, index + 1, current, allConfigs);

        // Try with '1'
        current[index] = '1';
        generateConfigurations(input, index + 1, current, allConfigs);
    } else {
        current[index] = input[index];
        generateConfigurations(input, index + 1, current, allConfigs);
    }
}

// Simulate the game and return the final two cards
pair<char, char> simulateGame(vector<char> cards) {
    while (cards.size() > 2) {
        // Masha's move (minimizing)
        auto mashaMove = minimax(cards, -1, 4, true).second;
        cards.erase(cards.begin() + mashaMove);

        if (cards.size() == 2) break;

        // Petya's move (maximizing)
        auto petyaMove = minimax(cards, -1, 4, false).second;
        cards.erase(cards.begin() + petyaMove);
    }

    return {cards[0], cards[1]};
}

int main() {
    string input;
    cin >> input;

    vector<char> current(input.size());
    vector<vector<char>> allConfigs;

    generateConfigurations(input, 0, current, allConfigs);

    set<string> outcomes;
    for (auto& config : allConfigs) {
        auto result = simulateGame(config);
        outcomes.insert(string(1, result.first) + result.second);
    }

    for (const auto& outcome : outcomes) {
        cout << outcome << endl;
    }

    return 0;
}

