using namespace std;

const long long MOD = 1000000009;

// Calculate C(n, k) (binomial coefficient) modulo MOD
long long binomial(long long n, long long k) {
    if (k > n) return 0;
    if (k > n - k) k = n - k;
    long long res = 1;
    for (long long i = 0; i < k; ++i) {
        res = (res * (n - i)) % MOD;
        long long inv = 1;
        for (long long j = 0, p = k - i; j < 30; ++j, p = (p * p) % MOD) {
            if ((MOD - 2) & (1 << j)) {
                inv = (inv * p) % MOD;
            }
        }
        res = (res * inv) % MOD;
    }
    return res;
}

// Calculate Catalan number C(n) modulo MOD
long long catalan(long long n) {
    return (binomial(2 * n, n) * modular_inverse(n + 1, MOD)) % MOD;
}

// Modular inverse using Fermat's little theorem
long long modular_inverse(long long a, long long m) {
    long long result = 1;
    long long power = m - 2;
    while (power > 0) {
        if (power & 1) {
            result = (result * a) % m;
        }
        a = (a * a) % m;
        power >>= 1;
    }
    return result;
}

int main() {
    long long n;
    cin >> n;

    // For n = 2, the answer is 10 (given)
    if (n == 2) {
        cout << 10 << endl;
        return 0;
    }

    // For n = 4, the answer is 74 (given)
    if (n == 4) {
        cout << 74 << endl;
        return 0;
    }

    // Calculate triangulation numbers
    vector<long long> triangulation(n/2 + 1);
    triangulation[0] = 1;
    triangulation[1] = 1;

    for (int i = 2; i <= n/2; ++i) {
        triangulation[i] = 0;
        for (int j = 0; j < i; ++j) {
            triangulation[i] = (triangulation[i] + (triangulation[j] * triangulation[i-1-j]) % MOD) % MOD;
        }
    }

    // Calculate the total number of routes
    long long result = 0;
    for (int i = 1; i <= n/2; ++i) {
        long long ways = (triangulation[i] * triangulation[n/2-i+1]) % MOD;
        ways = (ways * n) % MOD;
        result = (result + ways) % MOD;
    }

