#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

using namespace std;

double timeToReachDistance(double d, double v, double a) {
    double t_acc = v / a;
    double d_acc = 0.5 * a * t_acc * t_acc;

    if (d_acc >= d) {
        return sqrt(2 * d / a);
    } else {
        return t_acc + (d - d_acc) / v;
    }
}

int main() {
    int n, a, d;
    cin >> n >> a >> d;

    vector<pair<int, int>> trolleys(n);
    for (int i = 0; i < n; i++) {
        cin >> trolleys[i].first >> trolleys[i].second;
    }

    vector<double> arrivalTime(n);

    for (int i = 0; i < n; i++) {
        int startTime = trolleys[i].first;
        int maxSpeed = trolleys[i].second;
        double minTime = startTime + timeToReachDistance(d, maxSpeed, a);

        for (int j = 0; j < i; j++) {
            if (arrivalTime[j] > minTime) {
                double t = trolleys[i].first;
                double v = 0;
                double x = 0;

                while (true) {
                    double tj = trolleys[j].first;
                    double vj = 0;
                    double xj = 0;

                    double time_to_arrive = timeToReachDistance(d - x, maxSpeed, a);
                    double potential_arrival = t + time_to_arrive;

                    if (potential_arrival <= arrivalTime[j]) {
                        minTime = potential_arrival;
                        break;
                    }

                    // Simulate trolley j's movement
                    for (double dt = 0.0001; tj < t; tj += dt) {
                        if (vj < trolleys[j].second) {
                            vj += a * dt;
                            if (vj > trolleys[j].second) vj = trolleys[j].second;
                        }
                        xj += vj * dt;
                    }

                    // Check if trolley i can catch up with trolley j
                    double dx = xj - x;
                    if (dx <= 0) {
                        break;  // Already caught up
                    }

                    // Calculate time to catch up
                    double time_to_catch = 0;

                    if (maxSpeed <= trolleys[j].second) {
                        // Can't catch up with higher max speed
                        minTime = arrivalTime[j];
                        break;
                    }

                    double v_max = maxSpeed;
                    double acceleration_time = (v_max - v) / a;
                    double acceleration_dist = v * acceleration_time + 0.5 * a * acceleration_time * acceleration_time;

                    if (acceleration_dist >= dx) {
                        // Solve quadratic equation: x + v*t + 0.5*a*t^2 = xj
                        double b = v;
                        double c = x - xj;
                        time_to_catch = (-b + sqrt(b*b - 4 * 0.5 * a * c)) / (2 * 0.5 * a);
                    } else {
                        // Accelerate to max speed then maintain it
                        time_to_catch = acceleration_time + (dx - acceleration_dist) / v_max;
                    }

                    t += time_to_catch;
                    x = xj;
                    v = trolleys[j].second;  // matching speed after catching up

                    if (x >= d) {
                        minTime = arrivalTime[j];
                        break;
                    }

                    // Calculate remaining time
                    double remaining_dist = d - x;
                    double time_to_finish = remaining_dist / v;  // Already at max speed of trolley j
                    minTime = t + time_to_finish;
                    break;
                }

                minTime = max(minTime, arrivalTime[j]);
            }
        }

        arrivalTime[i] = minTime;
    }

    for (int i = 0; i < n; i++) {
        cout << fixed << setprecision(10) << arrivalTime[i] << endl;
    }

    return 0;
}

