struct Trolley {
    double t, v, arrival_time;
    int index;
};

double calc_min_time(double d, double v_max, double a) {
    double t_accel = v_max / a;
    double d_accel = 0.5 * a * t_accel * t_accel;

    if (d_accel >= d) {
        // Distance is so short that max speed is never reached
        return sqrt(2 * d / a);
    } else {
        // First accelerate to max speed, then cruise
        double d_cruise = d - d_accel;
        double t_cruise = d_cruise / v_max;
        return t_accel + t_cruise;
    }
}

double calc_catch_up_time(Trolley& leading, Trolley& following, double a) {
    // Solve quadratic equation to find when the following trolley catches up
    double A = 0.5 * a;
    double B = following.v;
    double C = leading.arrival_time - following.t - following.v * (leading.arrival_time - following.t);

    if (C <= 0) {
        return -1; // No solution or trivial solution
    }

    double discriminant = B * B + 4 * A * C;
    if (discriminant < 0) {
        return -1; // No real solution
    }

    double t1 = (-B + sqrt(discriminant)) / (2 * A);
    double t2 = (-B - sqrt(discriminant)) / (2 * A);

    if (t1 > 0) return t1 + following.t;
    if (t2 > 0) return t2 + following.t;
    return -1;
}

