// Function to calculate time to reach a distance with maximum acceleration and maximum speed
double time_to_reach(double dist, double max_accel, double max_speed) {
    double time_to_max_speed = max_speed / max_accel;
    double dist_at_max_speed = 0.5 * max_accel * time_to_max_speed * time_to_max_speed;

    if (dist <= dist_at_max_speed) {
        // Can't reach max speed, will accelerate all the way
        return sqrt(2.0 * dist / max_accel);
    } else {
        // Will reach max speed and then maintain it
        double remaining_dist = dist - dist_at_max_speed;
        double time_at_max_speed = remaining_dist / max_speed;
        return time_to_max_speed + time_at_max_speed;
    }
}

// Function to calculate distance covered in a given time with maximum acceleration and maximum speed
double distance_covered(double time, double max_accel, double max_speed) {
    double time_to_max_speed = max_speed / max_accel;

    if (time <= time_to_max_speed) {
        // Still accelerating
        return 0.5 * max_accel * time * time;
    } else {
        // Reached max speed
        double dist_at_max_speed = 0.5 * max_accel * time_to_max_speed * time_to_max_speed;
        double remaining_time = time - time_to_max_speed;
        return dist_at_max_speed + max_speed * remaining_time;
    }
}

