#include <iostream>
#include <vector>

int main() {
    int n, m, c;
    std::cin >> n >> m >> c;

    std::vector<int> message(n);
    for (int i = 0; i < n; i++) {
        std::cin >> message[i];
    }

    std::vector<int> key(m);
    for (int i = 0; i < m; i++) {
        std::cin >> key[i];
    }

    // Compute prefix sums of the key shifted by each position
    std::vector<int> prefixSum(n + 1, 0);

    for (int i = 0; i <= n - m; i++) {
        prefixSum[i] = (prefixSum[i] + key[0]) % c;
        if (i + m < n + 1) {
            prefixSum[i + m] = (prefixSum[i + m] - key[0] + c) % c;
        }
    }

    // Calculate the cumulative effect
    for (int i = 1; i < n + 1; i++) {
        prefixSum[i] = (prefixSum[i] + prefixSum[i - 1]) % c;
    }

    // Apply encryption to the message
    for (int i = 0; i < n; i++) {
        int offset = 0;
        for (int j = 0; j < m && i - j >= 0; j++) {
            int keyIndex = (m - 1) - j;
            int steps = i - j + 1;
            if (steps <= n - m + 1) {
                offset = (offset + key[keyIndex]) % c;
            }
        }
        message[i] = (message[i] + offset) % c;
    }

    // Print the encrypted message
    for (int i = 0; i < n; i++) {
        std::cout << message[i];
        if (i < n - 1) {
            std::cout << " ";
        }
    }
    std::cout << std::endl;

    return 0;
}

