    for (int i = 0; i < m; i++) {
        cin >> b[i];
    }

    // Precompute the total impact of each key position
    vector<int> count(m, 0);
    for (int i = 0; i < n - m + 1; i++) {
        count[0]++;
    }

    for (int i = 1; i < m; i++) {
        count[i] = count[i-1] - 1;
    }

    // Apply the key with the right frequency
    for (int i = 0; i < n; i++) {
        int keyContributions = 0;

        // Calculate how many times each key element affects position i
        for (int j = 0; j < m && i - j >= 0; j++) {
            int keyPos = m - 1 - j;
            int startPos = i - j;

            if (startPos <= n - m) {
                int times;
                if (startPos == 0) {
                    times = count[keyPos];
                } else {
                    times = count[keyPos] - count[0] + (n - m + 1 - startPos);
                }

                keyContributions = (keyContributions + (b[keyPos] * times) % c) % c;
            }
        }

        a[i] = (a[i] + keyContributions) % c;
    }

    // Output the encrypted message
    for (int i = 0; i < n; i++) {
        cout << a[i];
        if (i < n - 1) cout << " ";
    }
    cout << endl;

