        for (long long i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                best_next = std::max(best_next, n / i);
            }
        }
        n = best_next;
        sequence.push_back(n);
    }

    long long result = 0;
    for (long long num : sequence) {
        result += num;
    }

    return result;
}

