#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

typedef long long ll;

// Get all divisors of n
vector<ll> get_divisors(ll n) {
    vector<ll> divisors;
    for (ll i = 1; i <= sqrt(n); ++i) {
        if (n % i == 0) {
            divisors.push_back(i);
            if (i != n / i) {
                divisors.push_back(n / i);
            }
        }
    }
    return divisors;
}

// Calculate the maximum result starting from n
ll max_result(ll n) {
    if (n == 1) return 1;

    // Get all possible ways to arrange the pebbles
    vector<ll> divisors = get_divisors(n);

    // Filter divisors greater than 1 (as a > 1 is required)
    vector<ll> valid_divisors;
    for (ll d : divisors) {
        if (d > 1) {
            valid_divisors.push_back(n / d); // This will be the number of pebbles in a row (b)
        }
    }

    // Sort to try smaller numbers of pebbles first (which might lead to longer games)
    sort(valid_divisors.begin(), valid_divisors.end());

    ll max_result_val = 0;
    for (ll next_pebbles : valid_divisors) {
        ll result = n + max_result(next_pebbles);
        max_result_val = max(max_result_val, result);
    }

    return max_result_val;
}

// Optimized version with memoization
ll max_result_memo(ll n, unordered_map<ll, ll>& memo) {
    if (n == 1) return 1;
    if (memo.count(n)) return memo[n];

    vector<ll> divisors = get_divisors(n);

    vector<ll> valid_divisors;
    for (ll d : divisors) {
        if (d > 1) {
            valid_divisors.push_back(n / d);
        }
    }

    ll max_result_val = 0;
    for (ll next_pebbles : valid_divisors) {
        ll result = n + max_result_memo(next_pebbles, memo);
        max_result_val = max(max_result_val, result);
    }

    memo[n] = max_result_val;
    return max_result_val;
}

int main() {
    ll n;
    cin >> n;

    unordered_map<ll, ll> memo;
    cout << max_result_memo(n, memo) << endl;

    return 0;
}

