unordered_map<long long, long long> memo;

long long solve(long long n) {
    if (n == 1) return 1;

    if (memo.count(n) > 0) return memo[n];

    long long max_result = 0;

    // Try all possible divisors of n
    for (long long i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            if (i > 1) {
                max_result = max(max_result, n/i + solve(i));
            }
            if (n/i != i && n/i > 1) {
                max_result = max(max_result, i + solve(n/i));
            }
        }
    }

    memo[n] = max_result;
    return max_result;
}

int main() {
    long long n;
    cin >> n;

