long long maximumGameResult(long long n) {
    long long result = n;

    while (n > 1) {
        // Find the smallest divisor of n
        long long nextPebbles = 0;
        for (long long i = 2; i * i <= n; ++i) {
            if (n % i == 0) {
                nextPebbles = n / i;
                break;
            }
        }

        // If no divisor found, n is prime, so we take all rows of 1 pebble
        if (nextPebbles == 0) {
            nextPebbles = 1;
        }

        n = nextPebbles;
        result += n;
    }

    return result;
}

