#include <iostream>
#include <string>
#include <set>
#include <vector>

using namespace std;

struct Point {
    int x, y;

    Point(int x = 0, int y = 0) : x(x), y(y) {}

    bool operator<(const Point& other) const {
        if (x != other.x) return x < other.x;
        return y < other.y;
    }
};

void backtrack(vector<string>& movements, int idx, Point current, set<Point>& destinations) {
    if (idx == movements.size()) {
        destinations.insert(current);
        return;
    }

    for (char move : movements[idx]) {
        Point next = current;
        if (move == 'U') next.y++;
        else if (move == 'D') next.y--;
        else if (move == 'L') next.x--;
        else if (move == 'R') next.x++;

        backtrack(movements, idx + 1, next, destinations);
    }
}

int main() {
    int n;
    cin >> n;

    vector<string> movements(n);
    for (int i = 0; i < n; i++) {
        cin >> movements[i];
    }

    // Forward simulation from (0, 0)
    set<Point> destinations;
    backtrack(movements, 0, Point(0, 0), destinations);

    // Reverse the movements and calculate possible origins
    for (int i = 0; i < n / 2; i++) {
        swap(movements[i], movements[n - 1 - i]);
    }

    for (string& s : movements) {
        for (char& c : s) {
            if (c == 'U') c = 'D';
            else if (c == 'D') c = 'U';
            else if (c == 'L') c = 'R';
            else if (c == 'R') c = 'L';
        }
    }

    // Simulate from each possible destination
    set<Point> origins;
    for (const Point& start : destinations) {
        set<Point> temp;
        backtrack(movements, 0, start, temp);
        for (const Point& p : temp) {
            origins.insert(p);
        }
    }

    cout << origins.size() << endl;

    return 0;
}

