using namespace std;

const long long MOD = 1000000007;

// Matrix multiplication modulo MOD
vector<vector<long long>> matrixMultiply(const vector<vector<long long>>& A, const vector<vector<long long>>& B) {
    vector<vector<long long>> C(2, vector<long long>(2, 0));

    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            for (int k = 0; k < 2; k++) {
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
            }
        }
    }

    return C;
}

// Matrix exponentiation modulo MOD
vector<vector<long long>> matrixPower(vector<vector<long long>> A, long long n) {
    vector<vector<long long>> result = {{1, 0}, {0, 1}}; // Identity matrix

    while (n > 0) {
        if (n % 2 == 1) {
            result = matrixMultiply(result, A);
        }
        A = matrixMultiply(A, A);
        n /= 2;
    }

    return result;
}

int main() {
    long long n;
    cin >> n;

    if (n == 0) {
        cout << 1 << endl;
        return 0;
    }

    // The matrix represents the recurrence relation:
    // up[n] = 3*up[n-1] + down[n-1]
    // down[n] = up[n-1] + 3*down[n-1]
    vector<vector<long long>> transformation = {{3, 1}, {1, 3}};

    // Compute the matrix power
    vector<vector<long long>> resultMatrix = matrixPower(transformation, n);

    // Initial state: 1 plant pointing upwards and 0 pointing downwards
    long long upPlants = (resultMatrix[0][0] * 1) % MOD;

    cout << upPlants << endl;

    return 0;
}

