const int MOD = 1000000007;

// Matrix multiplication modulo MOD
vector<vector<long long>> multiply(const vector<vector<long long>>& A, const vector<vector<long long>>& B) {
    int n = A.size();
    vector<vector<long long>> C(n, vector<long long>(n, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
            }
        }
    }
    return C;
}

// Matrix exponentiation modulo MOD
vector<vector<long long>> pow(vector<vector<long long>> A, long long n) {
    int size = A.size();
    vector<vector<long long>> result(size, vector<long long>(size, 0));
    for (int i = 0; i < size; i++) {
        result[i][i] = 1; // Identity matrix
    }

    while (n > 0) {
        if (n % 2 == 1) {
            result = multiply(result, A);
        }
        A = multiply(A, A);
        n /= 2;
    }

    return result;
}

