using namespace std;

// Define a 2x2 matrix for the recurrence relation
struct Matrix {
    long long a, b, c, d;
    Matrix(long long a = 1, long long b = 0, long long c = 0, long long d = 1) : a(a), b(b), c(c), d(d) {}
};

// Function to multiply two matrices
Matrix multiply(const Matrix& A, const Matrix& B, long long mod) {
    Matrix C;
    C.a = (A.a * B.a + A.b * B.c) % mod;
    C.b = (A.a * B.b + A.b * B.d) % mod;
    C.c = (A.c * B.a + A.d * B.c) % mod;
    C.d = (A.c * B.b + A.d * B.d) % mod;
    return C;
}

// Function to compute matrix power using binary exponentiation
Matrix power(Matrix A, long long n, long long mod) {
    Matrix result(1, 0, 0, 1); // Identity matrix

    while (n > 0) {
        if (n % 2 == 1) {
            result = multiply(result, A, mod);
        }
        A = multiply(A, A, mod);
        n /= 2;
    }

    return result;
}

int main() {
    long long n;
    cin >> n;

    if (n == 0) {
        cout << 1 << endl;
        return 0;
    }

    const long long MOD = 1000000007;

    // The recurrence relation is:
    // up(n+1) = 3 * up(n) + down(n)
    // down(n+1) = up(n) + 3 * down(n)

    // We can represent this as a matrix:
    // [ up(n+1) ]   = [ 3 1 ] * [ up(n) ]
    // [ down(n+1) ]   [ 1 3 ]   [ down(n) ]

