pair<long long, long long> fib(long long n, unordered_map<long long, pair<long long, long long>>& memo) {
    if (n == 0) return {0, 1};
    if (memo.count(n)) return memo[n];

    pair<long long, long long> ab;
    if (n % 2 == 0) {
        long long k = n / 2;
        pair<long long, long long> p = fib(k, memo);
        long long a = p.first;
        long long b = p.second;

        ab.first = (a * (2 * b - a)) % MOD;
        ab.second = (a * a + b * b) % MOD;
    } else {
        long long k = (n - 1) / 2;
        pair<long long, long long> p = fib(k, memo);
        long long a = p.first;
        long long b = p.second;

        ab.first = (a * a + b * b) % MOD;
        ab.second = (b * (2 * a + b)) % MOD;
    }

    memo[n] = ab;
    return ab;
}

