using namespace std;

// Function to calculate modular exponentiation (a^b % mod)
long long mod_pow(long long a, long long b, long long mod) {
    long long result = 1;
    a %= mod;
    while (b > 0) {
        if (b & 1) {
            result = (result * a) % mod;
        }
        a = (a * a) % mod;
        b >>= 1;
    }
    return result;
}

// Function to calculate modular inverse using Fermat's little theorem
long long mod_inverse(long long a, long long mod) {
    return mod_pow(a, mod - 2, mod);
}

// Function to calculate nCr % mod
long long binomial_coefficient(long long n, long long r, long long mod) {
    if (r == 0) return 1;

    // Calculate factorial values
    vector<long long> factorial(n + 1);
    factorial[0] = 1;
    for (long long i = 1; i <= n; i++) {
        factorial[i] = (factorial[i - 1] * i) % mod;
    }

    // Calculate nCr using the formula: n! / (r! * (n - r)!)
    long long result = factorial[n];
    result = (result * mod_inverse(factorial[r], mod)) % mod;
    result = (result * mod_inverse(factorial[n - r], mod)) % mod;

    return result;
}

int main() {
    long long n, m;
    cin >> n >> m;

    // The minimum time required is 2*n - 1
    // For higher n, the number of moves required is 3^n - 2^n
    if (n == 1) {
        cout << 2 % m << endl;
    } else if (n == 2) {
        cout << 5 % m << endl;
    } else if (n == 3) {
        cout << 26 % m << endl;
