        for (int i = 0; i < k; i++) {
            int v1 = 0;
            int v2 = 1;
            int v3 = i + 2;

            graph[v1][v2] = graph[v2][v1] = '1';
            graph[v1][v3] = graph[v3][v1] = '1';
            graph[v2][v3] = graph[v3][v2] = '1';

            cyclesCreated++;
