int main() {
    int n;
    cin >> n;

    vector<double> p(n);
    for (int i = 0; i < n; i++) {
        cin >> p[i];
    }

    // dp[i][0] - expected score ending with state 0 (no streak)
    // dp[i][1] - expected score ending with state 1 (streak of length 1)
    // dp[i][j] - expected score ending with state j (streak of length j)
    vector<vector<double>> dp(n + 1, vector<double>(n + 1, 0));

    for (int i = 1; i <= n; i++) {
        // Case when we got an 'X' - no streak
        dp[i][0] = dp[i-1][0] * (1 - p[i-1]) + 
                  dp[i-1][1] * (1 - p[i-1]) + 
                  dp[i-1][2] * (1 - p[i-1]) + 
                  dp[i-1][3] * (1 - p[i-1]) + 
                  dp[i-1][4] * (1 - p[i-1]) +
                  dp[i-1][5] * (1 - p[i-1]);

        // Case when we got an 'O' - streak of length 1
        dp[i][1] = dp[i-1][0] * p[i-1] + 1;

        // Cases when we extend the streak
        for (int j = 2; j <= i; j++) {
            dp[i][j] = dp[i-1][j-1] * p[i-1] + j*j - (j-1)*(j-1);
        }
    }

    double expected_score = 0;
    for (int j = 0; j <= n; j++) {
        expected_score += dp[n][j];
    }

    cout << fixed << setprecision(15) << expected_score << endl;

    return 0;
}

