double solve(const vector<double>& p, int n) {
    // dp[i][j] - expected score ending at position i with:
    // j=0: ending in a streak of O's
    // j=1: ending with X
    vector<vector<double>> dp(n + 1, vector<double>(2, 0.0));

    // dp2[i] - expected square of the length of streak ending at position i
    vector<double> dp2(n + 1, 0.0);

    for (int i = 1; i <= n; i++) {
        // Ending with O (continuing streak)
        dp[i][0] = (dp[i-1][0] + 1) * p[i-1];

        // Ending with O (starting streak after X)
