using ll = long long;

int main() {
    int m, k;
    cin >> m >> k;

    int n = m + 1; // number of cities
    vector<int> d(m), s(m);

    for (int i = 0; i < m; i++) {
        cin >> d[i];
    }

    for (int i = 0; i < m; i++) {
        cin >> s[i];
    }

    // dp[i][j] = minimum time to reach city i+1 with j fuel
    vector<vector<ll>> dp(n, vector<ll>(2001, LLONG_MAX));
    dp[0][s[0]] = 0; // start at city 1 with s[0] fuel

    for (int i = 0; i < n - 1; i++) {
        // Sort fuel amounts in decreasing order for current city
        vector<pair<int, ll>> fuels;
        for (int j = 0; j <= 2000; j++) {
            if (dp[i][j] != LLONG_MAX) {
                fuels.push_back({j, dp[i][j]});
            }
        }
        sort(fuels.begin(), fuels.end());

        // Process each possible fuel amount
        for (auto [fuel, time] : fuels) {
            // If we have enough fuel to go to the next city
            if (fuel >= d[i]) {
                int new_fuel = fuel - d[i];
                if (i + 1 < m) {
                    new_fuel += s[i + 1]; // Get fuel at the next city
                }
                dp[i + 1][new_fuel] = min(dp[i + 1][new_fuel], time + d[i]);
            }

            // Stay in current city to refuel
            if (i < m) {
                ll next_refuel_time = time + k - (time % k);
                if (time % k == 0) next_refuel_time = time;
                int new_fuel = fuel + s[i];
                dp[i][new_fuel] = min(dp[i][new_fuel], next_refuel_time);
            }
        }
    }

    // Find minimum time to reach the last city
    ll ans = LLONG_MAX;
    for (int j = 0; j <= 2000; j++) {
        if (dp[n - 1][j] != LLONG_MAX) {
            ans = min(ans, dp[n - 1][j]);
        }
    }

    cout << ans << endl;

    return 0;
}

