    vector<int> s(m); // fuel supplies
    for (int i = 0; i < m; i++) {
        cin >> s[i];
    }

    // Dijkstra's algorithm
    vector<long long> dist(n, LLONG_MAX);
    dist[0] = 0; // starting from city c1 at time 0

    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    pq.push({0, 0});

    vector<long long> fuel(n, 0);
    fuel[0] = s[0]; // initial fuel at city c1

    while (!pq.empty()) {
        long long time = pq.top().first;
        int city = pq.top().second;
        pq.pop();

        if (time > dist[city]) continue;

        if (city == n - 1) break; // reached the last city

        // Try to go to the next city
        if (fuel[city] >= d[city]) {
            long long new_time = time + d[city];
            long long remaining_fuel = fuel[city] - d[city];

            if (city + 1 < n - 1) { // not the last city
                remaining_fuel += s[city + 1]; // get fuel from the next city
            }

            if (dist[city + 1] > new_time) {
                dist[city + 1] = new_time;
                fuel[city + 1] = remaining_fuel;
                pq.push({new_time, city + 1});
            } else if (dist[city + 1] == new_time && fuel[city + 1] < remaining_fuel) {
                fuel[city + 1] = remaining_fuel;
                pq.push({new_time, city + 1});
            }
        }

        // Stay in the current city to wait for fuel refresh
        long long new_time = time + k;
        long long new_fuel = fuel[city] + s[city];

        pq.push({new_time, city});
    }

