using namespace std;

struct State {
    int city;
    int fuel;
    long long time;

    State(int c, int f, long long t) : city(c), fuel(f), time(t) {}

    bool operator>(const State& other) const {
        return time > other.time;
    }
};

int main() {
    int m, k;
    cin >> m >> k;

    int n = m + 1;

    vector<int> d(m);
    for (int i = 0; i < m; i++) {
        cin >> d[i];
    }

    vector<int> s(m);
    for (int i = 0; i < m; i++) {
        cin >> s[i];
    }

    vector<vector<long long>> min_time(n, vector<long long>(k, LLONG_MAX));
    min_time[0][0] = 0;

    priority_queue<State, vector<State>, greater<State>> pq;
    pq.push(State(0, s[0], 0));

    while (!pq.empty()) {
        State curr = pq.top();
        pq.erase(pq.begin());

        int city = curr.city;
        int fuel = curr.fuel;
        long long time = curr.time;

        if (city == n - 1) {
            cout << time << endl;
            return 0;
        }

        // Wait for fuel to refresh
        if (city < m) {
            int wait_time = (k - (time % k)) % k;
            if (min_time[city][(time + wait_time) % k] > time + wait_time) {
                min_time[city][(time + wait_time) % k] = time + wait_time;
                pq.push(State(city, fuel + s[city], time + wait_time));
            }
        }

        // Drive to the next city if enough fuel
        if (city < m && fuel >= d[city]) {
            long long new_time = time + d[city];
            int new_fuel = fuel - d[city];

            if (city + 1 < m) {
                new_fuel += s[city + 1];
            }

            if (min_time[city + 1][new_time % k] > new_time) {
                min_time[city + 1][new_time % k] = new_time;
                pq.push(State(city + 1, new_fuel, new_time));
            }
        }
    }

    return 0;
}

