    for (int i = 1; i < n; i++) {
        dist_to_city[i] = dist_to_city[i-1] + d[i-1];
    }

    // We'll use a dynamic approach
    // dp[i] = minimum time to reach city i+1
    vector<long long> dp(n, 0);

    // Initial fuel at city c1
    long long fuel = s[0];

    for (int i = 1; i < n; i++) {
        // Distance to the next city
        int dist = d[i-1];

        // If we don't have enough fuel, we need to wait at this city
        if (fuel < dist) {
            // Calculate how many full cycles of k hours we need to wait
            long long cycles_needed = (dist - fuel + s[i-1] - 1) / s[i-1];
            dp[i] = dp[i-1] + cycles_needed * k + dist;
            // Remaining fuel after reaching the next city
            fuel = fuel + cycles_needed * s[i-1] - dist;
        } else {
            dp[i] = dp[i-1] + dist;
            fuel -= dist;
        }

        // Add the fuel supply of the current city (except for the last one)
        if (i < n-1) {
            fuel += s[i];
        }
    }

