        for (int j = i + 1; j < n - 1; ++j) {
            // Binary search for the rightmost point that is within distance d from points[i]
            int left = j + 1, right = n - 1, pos = j;
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (points[mid] - points[i] <= d) {
                    pos = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            // Add the number of valid triples with points[i] and points[j]
            count += pos - j;
        }
    }

    std::cout << count << std::endl;

