using namespace std;

vector<int> apply_permutation(const vector<int>& p, const vector<int>& q) {
    vector<int> result(p.size());
    for (size_t i = 0; i < p.size(); i++) {
        result[i] = p[q[i] - 1];
    }
    return result;
}

vector<int> apply_inverse_permutation(const vector<int>& p, const vector<int>& q) {
    vector<int> result(p.size());
    for (size_t i = 0; i < p.size(); i++) {
        result[q[i] - 1] = p[i];
    }
    return result;
}

bool bfs(const vector<int>& q, const vector<int>& s, int k) {
    int n = q.size();
    vector<int> identity(n);
    for (int i = 0; i < n; i++) {
        identity[i] = i + 1;
    }

    set<vector<int>> visited;
    queue<pair<vector<int>, int>> queue;

    queue.push({identity, 0});
    visited.insert(identity);

    while (!queue.empty()) {
        vector<int> current_perm = queue.front().first;
        int moves = queue.front().second;
        queue.pop();

        if (moves == k && current_perm == s) {
            return true;
        }

        if (moves < k) {
            // Apply q
            vector<int> next_perm1 = apply_permutation(current_perm, q);
            if (visited.find(next_perm1) == visited.end() || (next_perm1 == s && moves + 1 == k)) {
                queue.push({next_perm1, moves + 1});
                if (next_perm1 != s || moves + 1 == k) {
                    visited.insert(next_perm1);
                }
            }

            // Apply inverse of q
            vector<int> next_perm2 = apply_inverse_permutation(current_perm, q);
            if (visited.find(next_perm2) == visited.end() || (next_perm2 == s && moves + 1 == k)) {
                queue.push({next_perm2, moves + 1});
                if (next_perm2 != s || moves + 1 == k) {
                    visited.insert(next_perm2);
                }
            }
        }
    }

    return false;
}

