    cin >> n >> k;

    vector<int> q(n);
    for (int i = 0; i < n; i++) {
        cin >> q[i];
    }

    vector<int> s(n);
    for (int i = 0; i < n; i++) {
        cin >> s[i];
    }

    if (bfs(q, s, k)) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

