}

vector<int> applyInversePermutation(const vector<int>& p, const vector<int>& q) {
    vector<int> result(p.size());
    for (int i = 0; i < p.size(); ++i) {
        result[q[i] - 1] = p[i];
    }
    return result;
}

string encode(const vector<int>& perm) {
    string encoded = "";
    for (int x : perm) {
        encoded += to_string(x) + ",";
    }
    return encoded;
}

bool canReachPermutation(vector<int>& identity, vector<int>& q, vector<int>& target, int k) {
    queue<pair<vector<int>, int>> bfs;
    unordered_set<string> visited;

    bfs.push({identity, 0});
    visited.insert(encode(identity));

    while (!bfs.empty()) {
        auto [current, moves] = bfs.front();
        bfs.pop();

        if (moves == k && current == target) {
            return true;
        }

        if (moves < k) {
            // Apply direct permutation
            vector<int> nextDirect = applyPermutation(current, q);
            string nextDirectStr = encode(nextDirect);

            if (nextDirect == target && moves + 1 == k) {
                return true;
            }

            if (nextDirect != target && visited.find(nextDirectStr) == visited.end()) {
                bfs.push({nextDirect, moves + 1});
                visited.insert(nextDirectStr);
            }

            // Apply inverse permutation
            vector<int> nextInverse = applyInversePermutation(current, q);
            string nextInverseStr = encode(nextInverse);

            if (nextInverse == target && moves + 1 == k) {
                return true;
            }

            if (nextInverse != target && visited.find(nextInverseStr) == visited.end()) {
                bfs.push({nextInverse, moves + 1});
                visited.insert(nextInverseStr);
            }
        }
    }

    return false;
}

