bool canReachPermutation(const vector<int>& q, const vector<int>& target, int k) {
    int n = q.size();

    // Define a set to store visited permutations
    unordered_set<string> visited;

    // Start with identity permutation 
    vector<int> current(n);
    for (int i = 0; i < n; i++) {
        current[i] = i + 1;
    }

    // Convert to string for set operations
    string currentStr;
    for (int i = 0; i < n; i++) {
        currentStr += to_string(current[i]) + " ";
    }
    visited.insert(currentStr);

    // Check all 2^k possible sequences of coin tosses
    for (int mask = 0; mask < (1 << k); mask++) {
        vector<int> perm(n);
        for (int i = 0; i < n; i++) {
            perm[i] = i + 1;  // Start with identity
        }

        bool valid = true;

        for (int move = 0; move < k; move++) {
            // Create a temp vector for the next permutation
            vector<int> next(n);

            if ((mask >> move) & 1) {
                // Heads: Apply q
                for (int i = 0; i < n; i++) {
                    next[i] = perm[q[i] - 1];
                }
            } else {
                // Tails: Apply inverse of q
                for (int i = 0; i < n; i++) {
                    next[q[i] - 1] = perm[i];
                }
            }

            perm = next;

            if (move < k - 1) {
                // Create string representation for checking visited status
                string permStr;
                for (int i = 0; i < n; i++) {
                    permStr += to_string(perm[i]) + " ";
                }

                // If this is Masha's permutation before the kth move, it's invalid
                if (perm == target) {
                    valid = false;
                    break;
                }
            }
        }

        // After k moves, check if we have Masha's permutation
        if (valid && perm == target) {
            return true;
        }
    }

    return false;
}

