#include <queue>
#include <unordered_set>
#include <string>

using namespace std;

// Apply permutation q to permutation p
vector<int> apply_q(const vector<int>& p, const vector<int>& q) {
    vector<int> result(p.size());
    for (int i = 0; i < p.size(); i++) {
        result[i] = p[q[i] - 1];
    }
    return result;
}

// Apply inverse of permutation q to permutation p
vector<int> apply_inverse_q(const vector<int>& p, const vector<int>& q) {
    vector<int> result(p.size());
    for (int i = 0; i < p.size(); i++) {
        result[q[i] - 1] = p[i];
    }
    return result;
}

// Convert permutation to string for hashing
string perm_to_string(const vector<int>& p) {
    string result;
    for (int num : p) {
        result += to_string(num) + ",";
    }
    return result;
}

bool solve(int n, int k, const vector<int>& q, const vector<int>& s) {
    queue<pair<vector<int>, int>> queue;
    unordered_set<string> visited;

    // Start with identity permutation 1,2,...,n
    vector<int> identity(n);
    for (int i = 0; i < n; i++) {
        identity[i] = i + 1;
    }

    // Check if s is the identity permutation
    if (identity == s && k > 0) {
        return false;
    }

    queue.push({identity, 0});
    visited.insert(perm_to_string(identity));

    while (!queue.empty()) {
        auto [current, moves] = queue.front();
        queue.pop();

        if (moves == k) continue;

        // Try applying q
        vector<int> next1 = apply_q(current, q);
        string next1_str = perm_to_string(next1);

        // Check if we've reached Masha's permutation before the k-th move
        if (next1 == s && moves + 1 < k) {
            continue;
        }

        // Check if we've found Masha's permutation at exactly the k-th move
        if (next1 == s && moves + 1 == k) {
            return true;
        }

        if (visited.find(next1_str) == visited.end()) {
            visited.insert(next1_str);
            queue.push({next1, moves + 1});
        }

        // Try applying inverse of q
        vector<int> next2 = apply_inverse_q(current, q);
        string next2_str = perm_to_string(next2);

        // Check if we've reached Masha's permutation before the k-th move
        if (next2 == s && moves + 1 < k) {
            continue;
        }

        // Check if we've found Masha's permutation at exactly the k-th move
