const double PI = acos(-1.0);

int main() {
    int n;
    std::cin >> n;

    std::vector<double> angles;

    for (int i = 0; i < n; ++i) {
        int x, y;
        std::cin >> x >> y;

        // Calculate angle in radians
        double angle = atan2(y, x);

        // Convert to range [0, 2*PI)
        if (angle < 0) {
            angle += 2 * PI;
        }

        angles.push_back(angle);
    }

    // Sort angles
    std::sort(angles.begin(), angles.end());

    // Find maximum gap between consecutive angles
    double max_gap = angles[0] + 2 * PI - angles[n - 1];

    for (int i = 1; i < n; ++i) {
        max_gap = std::max(max_gap, angles[i] - angles[i - 1]);
    }

    // The view angle is 2*PI minus the maximum gap
    double view_angle = 2 * PI - max_gap;

    // Convert to degrees
    view_angle = view_angle * 180 / PI;

    // Output the result with required precision
    std::cout << std::fixed << std::setprecision(10) << view_angle << std::endl;

    return 0;
}

