// Function to calculate binomial coefficient C(n, r)
long long C(int n, int r) {
    if (r > n - r)
        r = n - r;

    long long res = 1;
    for (int i = 0; i < r; ++i) {
        res *= (n - i);
        res /= (i + 1);
    }

    return res;
}

// Function to solve the problem
double solve(int n, int m, int k) {
    // If we don't have enough 10 euro notes initially and from people with 10 euro, we can't succeed
    if (k + n < m)
        return 0.0;

    // If we have enough 10 euro notes initially to give change to everyone with 20 euro, we'll always succeed
    if (k >= m)
        return 1.0;

    // Calculate total number of possible orderings
    long long total_ways = C(n + m, n);

    // Calculate number of favorable orderings
    long long favorable_ways = 0;
    for (int i = 0; i <= m; ++i) {
        // i is the number of people with 20 euro that come before we run out of change
        if (k + n >= i && i <= m) {
            long long temp = C(k + n, i) * C(m, i);
            if ((i + 1) % 2 == 0)
                favorable_ways += temp;
            else
                favorable_ways -= temp;
        }
    }

    // The formula for favorable ways is more complex, using the principle of inclusion-exclusion
    favorable_ways = total_ways;
    for (int i = 1; i <= m; ++i) {
        if (k + n < i)
            break;

        long long ways = C(n + m - i - 1, n - i + k) * C(m, i);
        if (i % 2 == 1)
            favorable_ways -= ways;
        else
            favorable_ways += ways;
    }

    return (double)favorable_ways / total_ways;
}

