    if (k == 0 || k == n) return 1;

    vector<double> C(k + 1, 0);
    C[0] = 1;

    for (int i = 1; i <= n; i++) {
        for (int j = min(i, k); j > 0; j--) {
            C[j] = C[j] + C[j-1];
        }
    }

    return C[k];
}

