    int m;
    std::cin >> m;

    std::vector<int> discounts(m);
    for (int i = 0; i < m; i++) {
        std::cin >> discounts[i];
    }

    int n;
    std::cin >> n;

    std::vector<int> items(n);
    for (int i = 0; i < n; i++) {
        std::cin >> items[i];
    }

    // Sort discounts in ascending order
    std::sort(discounts.begin(), discounts.end());

    // Sort items in descending order
    std::sort(items.begin(), items.end(), std::greater<int>());

    // Calculate the optimal strategy
    int minCost = 0;
    int bestDiscount = discounts[0]; // Take the minimum discount as it's most valuable

    // Apply discounts optimally
    int remaining = n;
    while (remaining > 0) {
        if (remaining <= 2) {
            // If 2 or fewer items remain, just buy them
            for (int i = n - remaining; i < n; i++) {
                minCost += items[i];
            }
            remaining = 0;
        } else if (remaining >= bestDiscount + 2) {
            // Use the discount if we have enough items
            // Pay for the most expensive 'bestDiscount' items
            for (int i = n - remaining; i < n - remaining + bestDiscount; i++) {
                minCost += items[i];
            }
            remaining -= (bestDiscount + 2); // Subtract the free items too
        } else {
            // Not enough items to use the discount, buy the remaining ones
            for (int i = n - remaining; i < n; i++) {
                minCost += items[i];
            }
            remaining = 0;
        }
    }

    std::cout << minCost << std::endl;

    return 0;
}

