#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<int> species(n);
    vector<double> positions(n);

    for (int i = 0; i < n; i++) {
        cin >> species[i] >> positions[i];
    }

    int result = n;

    // Try all possible ways to keep a sequence of plants
    for (int mask = 0; mask < (1 << (n - 1)); mask++) {
        bool valid = true;
        int current_section = 1;
        int plants_to_move = 0;

        for (int i = 0; i < n; i++) {
            // Check if we need to increase the section
            if (i > 0 && (mask & (1 << (i - 1)))) {
                current_section++;
                if (current_section > m) {
                    valid = false;
                    break;
                }
            }

            // Check if the plant species matches the section
            if (species[i] != current_section) {
                plants_to_move++;
            }
        }

        // Make sure we used all m sections
        if (valid && current_section == m) {
            result = min(result, plants_to_move);
        }
    }

    // For larger inputs, use dynamic programming
    if (n <= 200) {
        cout << result << endl;
        return 0;
    }

    // dp[i][j] = minimum number of plants to replant if we consider 
    // first i plants and have j sections
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, n));
    dp[0][0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            // Try all possible positions for the last border
            for (int k = i; k >= j; k--) {
                int cost = 0;
                for (int p = k; p < i; p++) {
                    if (species[p] != j) cost++;
                }
                dp[i][j] = min(dp[i][j], dp[k-1][j-1] + cost);
            }
        }
    }

    cout << dp[n][m] << endl;
    return 0;
}

