    }

    vector<vector<int>> dp(n + 1, vector<int>(m));

    // Initialize DP table
    for (int j = 0; j < m; j++) {
        dp[0][j] = 0;
    }

    // Fill DP table
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < m; j++) {
            dp[i][j] = n; // Initialize with a large value

            for (int k = 0; k < m; k++) {
                int additional_cost = (species[i - 1] != j) ? 1 : 0;

                // Can only place section j after section k if j > k
                if (j > k) {
                    dp[i][j] = min(dp[i][j], dp[i - 1][k] + additional_cost);
                }
                // If j == k, we're still in the same section
                else if (j == k) {
                    dp[i][j] = min(dp[i][j], dp[i - 1][j] + additional_cost);
                }
            }
        }
    }

    // Find minimum replants among all possible ending sections
    int min_replants = n;
    for (int j = 0; j < m; j++) {
        min_replants = min(min_replants, dp[n][j]);
    }

