            // Use this plant for section j
            if (species[i-1] == j) {
                dp[i][j] = min(dp[i][j], dp[i-1][j]);
            }

            // Start section j with this plant
            dp[i][j] = min(dp[i][j], dp[i-1][j-1] + (species[i-1] != j));
