            }
        }
    }

    // Special case for n=1
    if (n == 1) return 1;

    std::vector<std::pair<int, int>> factorization;  // (prime, exponent)

    // Factor n into its prime factorization
    int remaining = n;
    for (int prime : primes) {
        if (prime * prime > remaining) break;

        int exponent = 0;
        while (remaining % prime == 0) {
            remaining /= prime;
            exponent++;
        }

        if (exponent > 0) {
            factorization.push_back({prime, exponent});
        }
    }

    if (remaining > 1) {
        factorization.push_back({remaining, 1});
    }

    // If n is already prime, return p^(n-1)
    if (factorization.size() == 1 && factorization[0].first == n) {
        return (long long)pow(2, n - 1);
    }

    // Try to find the best factorization minimizing the result
    std::vector<int> exponents;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            exponents.push_back(i - 1);
            if (i != n / i) {
