        std::cout << 0 << std::endl;
        return 0;
    }

    int layer = std::max(std::abs(x), std::abs(y));

    if (x == layer && y < layer) {
        // Right edge
        std::cout << (4 * layer - 3) << std::endl;
    } else if (y == layer) {
        // Top edge
        std::cout << (4 * (layer - 1)) << std::endl;
    } else if (x == -layer) {
        // Left edge
        std::cout << (4 * layer - 1) << std::endl;
    } else if (y == -layer) {
        // Bottom edge
        std::cout << (4 * layer - 2) << std::endl;
    } else {
        int maxCoord = std::max(std::abs(x), std::abs(y));
        if (x == maxCoord && y > 0) {
            // Right edge top half
            std::cout << (4 * (maxCoord - 1)) << std::endl;
        } else if (x < 0 && y == maxCoord) {
            // Top edge left half
            std::cout << (4 * maxCoord - 1) << std::endl;
        } else if (x == -maxCoord && y < 0) {
            // Left edge bottom half
            std::cout << (4 * maxCoord - 2) << std::endl;
        } else if (x > 0 && y == -maxCoord) {
            // Bottom edge right half
