    } else if (y == layer && x > -layer) {
        // Top side, going left
        turns = 4 * layer - 2;
    } else if (x == -layer) {
        // Left side, going down
        turns = 4 * layer - 1;
    } else if (y == -layer) {
        // Bottom side, going right
        turns = 4 * layer;
    }

    // Calculate the position within the layer
    if (x == layer && y < layer) {
        // Right side, not at the top
        turns -= (layer - y);
    } else if (y == layer && x < layer && x > -layer) {
        // Top side, not at the corners
        turns -= (layer - x);
    } else if (x == -layer && y > -layer) {
        // Left side, not at the bottom
        turns -= (layer + y);
    } else if (y == -layer && x > -layer) {
        // Bottom side, not at the left corner
        turns -= (layer + x);
    }

