#include <iostream>
#include <cmath>

int main() {
    int x, y;
    std::cin >> x >> y;

    if (x == 0 && y == 0) {
        std::cout << 0 << std::endl;
        return 0;
    }

    int layerMax = std::max(std::abs(x), std::abs(y));
    int turns = 0;
    int currentX = 0, currentY = 0;
    int dx = 1, dy = 0;

    while (true) {
        // Move horizontally first
        int nextX = currentX + dx;
        if (std::abs(nextX) > layerMax) {
            // Change direction to vertical
            dx = 0;
            dy = (dx == 1) ? 1 : -1;
            turns++;
            continue;
        }
        currentX = nextX;

        if (currentX == x && currentY == y) break;

        // Move vertically
        int nextY = currentY + dy;
        if (std::abs(nextY) > layerMax) {
