    set<pair<int, int>> edges;

    for (int i = 1; i <= n; i++) {
        int j1 = i + favorites[i-1];
        int j2 = i - favorites[i-1];

        if (j1 >= 1 && j1 <= n) {
            if (edges.find({min(i, j1), max(i, j1)}) == edges.end()) {
                graph[i].push_back(j1);
                graph[j1].push_back(i);
                edges.insert({min(i, j1), max(i, j1)});
            }
        }

        if (j2 >= 1 && j2 <= n) {
            if (edges.find({min(i, j2), max(i, j2)}) == edges.end()) {
                graph[i].push_back(j2);
                graph[j2].push_back(i);
