bool dfs(int node, vector<vector<int>>& graph, vector<bool>& visited, vector<bool>& inStack) {
    visited[node] = true;
    inStack[node] = true;

    for (int neighbor : graph[node]) {
        if (!visited[neighbor]) {
            if (dfs(neighbor, graph, visited, inStack)) {
                return true;
            }
        } else if (inStack[neighbor]) {
