            total_sum -= (last_val + add_values.back());

            // Add the value that was previously added to the last element to the element before it
            if (add_values.back() != 0 && add_values.size() > 1) {
                add_values[add_values.size() - 2] += add_values.back();
            }

            seq.pop_back();
            add_values.pop_back();
        }

        double average = static_cast<double>(total_sum) / seq.size();
