// Calculate (a^b) % m
long long power_mod(long long a, long long b, long long m) {
    a %= m;
    long long res = 1;
    while (b > 0) {
        if (b & 1)
            res = (res * a) % m;
        a = (a * a) % m;
        b >>= 1;
    }
    return res;
}

// Find all prime factors of n
std::vector<long long> prime_factors(long long n) {
    std::vector<long long> factors;
    for (long long i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            factors.push_back(i);
            while (n % i == 0) {
                n /= i;
            }
        }
    }
    if (n > 1) {
        factors.push_back(n);
    }
    return factors;
}

// Check if g is a primitive root of p
bool is_primitive_root(long long g, long long p) {
    if (g <= 0 || g >= p)
        return false;

    // Find distinct prime factors of phi(p)
    long long phi_p = phi(p);
    std::vector<long long> factors = prime_factors(phi_p);

    // g is a primitive root if for every prime factor f of phi(p),
    // g^(phi(p)/f) mod p is not 1
    for (long long factor : factors) {
        if (power_mod(g, phi_p / factor, p) == 1)
            return false;
    }
    return true;
}

// Count primitive roots modulo p using Euler's theorem
long long count_primitive_roots(long long p) {
    if (p == 2)
        return 1; // Special case

