#include <iostream>
#include <unordered_map>
#include <vector>
#include <set>

int main() {
    int n;
    std::cin >> n;

    std::unordered_map<int, std::set<int>> graph;

    // Read the stamps
    for (int i = 0; i < n; i++) {
        int a, b;
        std::cin >> a >> b;
        graph[a].insert(b);
        graph[b].insert(a);
    }

    // Find endpoints (cities with only one connection)
    int start = -1;
    for (const auto& entry : graph) {
        if (entry.second.size() == 1) {
            start = entry.first;
            break;
        }
    }

    // Construct the path
    std::vector<int> path = {start};
    int current = start;

    while (path.size() <= n) {
        int next = *graph[current].begin();
        graph[next].erase(current);
        graph[current].erase(next);
        path.push_back(next);
        current = next;
    }

    // Output the path
    for (int city : path) {
        std::cout << city << " ";
    }

    return 0;
}

