#include <unordered_set>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;

    unordered_map<int, vector<int>> graph;
    unordered_map<int, int> degree;

    for (int i = 0; i < n; ++i) {
        int a, b;
        cin >> a >> b;

        graph[a].push_back(b);
        graph[b].push_back(a);

        degree[a]++;
        degree[b]++;
    }

    // Find start and end points (nodes with odd degree)
    int start = -1;
    for (const auto& pair : degree) {
        if (pair.second == 1) {
            start = pair.first;
            break;
        }
    }

    // If no node with degree 1 found, choose any node
    if (start == -1) {
        start = graph.begin()->first;
    }

    // Construct the path
    vector<int> path;
    path.push_back(start);

    int current = start;
    unordered_set<int> visited;
    visited.insert(current);

    while (true) {
        bool found = false;
        for (int next : graph[current]) {
            if (visited.find(next) == visited.end()) {
                path.push_back(next);
                visited.insert(next);
                current = next;
                found = true;
                break;
            }
        }

        if (!found) break;
    }

    // Print the path
    for (int i = 0; i < path.size(); ++i) {
        cout << path[i];
        if (i < path.size() - 1) cout << " ";
    }
    cout << endl;

    return 0;
}

