using namespace std;

int main() {
    int n;
    cin >> n;

    vector<pair<int, int>> tasks(n);
    for (int i = 0; i < n; i++) {
        cin >> tasks[i].first >> tasks[i].second;
    }

    int queueSize = 0;
    int maxQueueSize = 0;
    int lastSendTime = 0;
    int currentTime = 0;
    int taskIndex = 0;
    queue<int> messageQueue;

    while (!messageQueue.empty() || taskIndex < n) {
        if (messageQueue.empty()) {
            currentTime = tasks[taskIndex].first;
        }

        // Process all tasks that arrive at the current time
        while (taskIndex < n && tasks[taskIndex].first == currentTime) {
            queueSize += tasks[taskIndex].second;
            for (int i = 0; i < tasks[taskIndex].second; i++) {
                messageQueue.push(1);
            }
            taskIndex++;
        }

        maxQueueSize = max(maxQueueSize, queueSize);

        // Send a message if the queue is not empty
        if (!messageQueue.empty()) {
            messageQueue.pop();
            queueSize--;
            lastSendTime = currentTime + 1;
        }

        currentTime++;
    }

    cout << lastSendTime << " " << maxQueueSize << endl;

    return 0;
}

