    }

    int currentTime = 0;
    int queueSize = 0;
    int maxQueueSize = 0;
    long long totalMessages = 0;

    for (int i = 0; i < n; i++) {
        int taskTime = tasks[i].first;
        int messagesCount = tasks[i].second;

        // Process messages in queue until the time of the next task
        int processedMessages = min(queueSize, taskTime - currentTime);
        queueSize -= processedMessages;
        currentTime += processedMessages;

        // If there's still time left but no messages in queue, advance time
        if (currentTime < taskTime) {
            currentTime = taskTime;
        }

        // Add new messages to the queue
        queueSize += messagesCount;
        totalMessages += messagesCount;

        // Update max queue size
        maxQueueSize = max(maxQueueSize, queueSize);
    }

    // Calculate the finish time by adding remaining messages to current time
    long long finishTime = currentTime + queueSize;

    cout << finishTime << " " << maxQueueSize << endl;

    return 0;
}

