#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <set>
#include <map>
using namespace std;

// Direction names
const string dirs[] = {"R", "RU", "U", "LU", "L", "LD", "D", "RD"};
// Corresponding direction changes (dx, dy)
const int dx[] = {1, 1, 0, -1, -1, -1, 0, 1};
const int dy[] = {0, 1, 1, 1, 0, -1, -1, -1};

struct Position {
    int x, y;
    Position(int x, int y) : x(x), y(y) {}

    bool operator<(const Position& other) const {
        if (x != other.x) return x < other.x;
        return y < other.y;
    }
};

int main() {
    string start, end;
    cin >> start >> end;

    Position s(start[0] - 'a', start[1] - '1');
    Position e(end[0] - 'a', end[1] - '1');

    // BFS
    queue<Position> q;
    q.push(s);

    map<Position, Position> parent;
    map<Position, string> moves;

    parent[s] = s;

    while (!q.empty()) {
        Position current = q.front();
        q.pop();

        if (current.x == e.x && current.y == e.y)
            break;

        for (int i = 0; i < 8; i++) {
            int nx = current.x + dx[i];
            int ny = current.y + dy[i];

            if (nx >= 0 && nx < 8 && ny >= 0 && ny < 8) {
                Position next(nx, ny);
                if (parent.find(next) == parent.end()) {
                    parent[next] = current;
                    moves[next] = dirs[i];
                    q.push(next);
                }
            }
        }
    }

    // Reconstruct the path
    vector<string> path;
    Position current = e;

    while (!(current.x == s.x && current.y == s.y)) {
        Position prev = parent[current];
        path.push_back(moves[current]);
        current = prev;
    }

    // Reverse the path
    reverse(path.begin(), path.end());

    // Print the result
    cout << path.size() << endl;
    for (const string& move : path) {
        cout << move << endl;
    }

    return 0;
}

