const string moves[] = {"L", "R", "U", "D", "LU", "LD", "RU", "RD"};

struct Cell {
    int x, y;
    Cell(int _x, int _y) : x(_x), y(_y) {}

    bool operator==(const Cell& other) const {
        return x == other.x && y == other.y;
    }
};

struct CellHash {
    size_t operator()(const Cell& cell) const {
        return cell.x * 10 + cell.y;
    }
};

bool isValid(int x, int y) {
    return x >= 0 && x < 8 && y >= 0 && y < 8;
}

pair<int, vector<string>> bfs(Cell start, Cell target) {
    queue<Cell> q;
    q.push(start);

    unordered_map<Cell, Cell, CellHash> parent;
    unordered_map<Cell, int, CellHash> moveIndex;

    parent[start] = Cell(-1, -1);

    while (!q.empty()) {
        Cell curr = q.front();
        q.pop();

        if (curr == target) {
            // Construct the path
            vector<string> path;
            Cell c = curr;
            while (parent[c].x != -1) {
                path.push_back(moves[moveIndex[c]]);
                c = parent[c];
            }
            reverse(path.begin(), path.end());
            return {path.size(), path};
