// Directions: L, R, U, D, LU, LD, RU, RD
const int dx[] = {-1, 1, 0, 0, -1, -1, 1, 1};
const int dy[] = {0, 0, 1, -1, 1, -1, 1, -1};
const string dir_names[] = {"L", "R", "U", "D", "LU", "LD", "RU", "RD"};

struct Position {
    int x, y;
    Position(int _x, int _y) : x(_x), y(_y) {}
    bool operator==(const Position& other) const {
        return x == other.x && y == other.y;
    }
};

struct State {
    Position pos;
    vector<string> path;
    State(Position _pos, vector<string> _path) : pos(_pos), path(_path) {}
};

bool isValid(int x, int y) {
    return x >= 0 && x < 8 && y >= 0 && y < 8;
}

vector<string> findShortestPath(Position start, Position end) {
    queue<State> q;
    map<pair<int, int>, bool> visited;

    q.push(State(start, {}));
    visited[{start.x, start.y}] = true;

    while (!q.empty()) {
        State current = q.front();
        q.pop();

        if (current.pos == end) {
            return current.path;
        }

        for (int i = 0; i < 8; i++) {
            int nx = current.pos.x + dx[i];
            int ny = current.pos.y + dy[i];

            if (isValid(nx, ny) && !visited[{nx, ny}]) {
                vector<string> new_path = current.path;
                new_path.push_back(dir_names[i]);

                q.push(State(Position(nx, ny), new_path));
                visited[{nx, ny}] = true;
            }
        }
    }

    return {};
}

int main() {
    string s, t;
    cin >> s >> t;

    Position start(s[0] - 'a', s[1] - '1');
    Position end(t[0] - 'a', t[1] - '1');

    vector<string> path = findShortestPath(start, end);

