#include <vector>
#include <unordered_map>

using namespace std;

// DP solution to find valid email list
bool findValidEmails(const string& s, int pos, vector<string>& result, vector<int>& dp, unordered_map<int, vector<string>>& memo) {
    if (pos == s.length()) {
        return true;
    }

    if (dp[pos] != -1) {
        return dp[pos] == 1;
    }

    for (int i = pos; i < s.length() - 1; i++) {
        if (s[i] == '@') {
            bool foundAtInFirst = false;
            for (int j = pos; j < i; j++) {
                if (s[j] == '@') {
                    foundAtInFirst = true;
                    break;
                }
            }

            if (foundAtInFirst) continue;

            string email = s.substr(pos, i - pos + 1 + (s.length() - i - 1));
            bool validEmail = true;

            // Check if this is a valid email (contains exactly one @ and non-empty parts)
            int atCount = 0;
            for (char c : email) {
                if (c == '@') atCount++;
            }

            if (atCount != 1 || email[0] == '@' || email.back() == '@') {
                validEmail = false;
            }

            if (validEmail) {
                result.push_back(email);
                if (i + 1 == s.length()) {
                    dp[pos] = 1;
                    return true;
                }

                if (findValidEmails(s, i + 1, result, dp, memo)) {
                    dp[pos] = 1;
                    return true;
                }

                result.pop_back();
            }
        }
    }

    dp[pos] = 0;
    return false;
}

