    for (int i = pos; i < s.length() - 2; ++i) {
        for (int j = i + 1; j < s.length() - 1; ++j) {
            if (s[j] == '@') {
                string email = s.substr(pos, j - pos + 1 + (s.length() - j - 1));

                // Check if this is a valid email (has exactly one '@' and it's not at the beginning or end)
                int atCount = 0;
                bool validEmail = true;

                for (char c : email) {
                    if (c == '@') atCount++;
                }

                if (atCount != 1 || email[0] == '@' || email[email.length()-1] == '@') {
                    validEmail = false;
                }

                if (validEmail && i + 1 == s.length()) {
                    ans.push_back(email);
                    return true;
                }

                if (validEmail) {
                    ans.push_back(email.substr(0, j - pos + 1 + (s.length() - j - 1)));
                    if (dfs(s, j + 1)) return true;
                    ans.pop_back();
                }
            }
        }
    }

