    ifstream fin("input.txt");
    ofstream fout("output.txt");

    int n, X;
    fin >> n >> X;

    vector<Animal> animals(n);
    for (int i = 0; i < n; i++) {
        fin >> animals[i].food;
        animals[i].day = i + 1;
    }

    sort(animals.begin(), animals.end(), compareAnimals);

    int count = 0;
