using namespace std;

// Check if position (i, j) is a black square on the chessboard
bool isBlack(int i, int j) {
    return (i + j) % 2 == 0;
}

// Count corner-adjacent neighbors with the specified color
int countCornerNeighbors(const vector<vector<int>>& board, int i, int j, int color) {
    int count = 0;
    vector<pair<int, int>> corners = {{-1, -1}, {-1, 1}, {1, -1}, {1, 1}};

    for (auto& corner : corners) {
        int ni = i + corner.first;
        int nj = j + corner.second;
        if (ni >= 0 && ni < board.size() && nj >= 0 && nj < board[0].size() && board[ni][nj] == color) {
            count++;
        }
    }

    return count;
}

int main() {
    int n, m, x;
    cin >> n >> m >> x;

    if (x == 1) {
        // Count black squares initially
        int blackCount = (n * m + 1) / 2;
        cout << blackCount << endl;
        return 0;
    }

    // Initialize the board
    vector<vector<int>> board(n, vector<int>(m, -1));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (isBlack(i, j)) {
                board[i][j] = 0;  // Initially black squares are colored 0
            }
        }
    }

    int paintedCount = 0;
    int minute = 1;

    while (minute < x) {
        vector<pair<int, int>> toRepaint;

        // Find squares to repaint
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isBlack(i, j) && board[i][j] == 0 && 
                    countCornerNeighbors(board, i, j, minute - 1) == 4) {
                    toRepaint.push_back({i, j});
                }
            }
        }

        if (toRepaint.empty()) break;

        // Repaint squares
        for (auto& pos : toRepaint) {
            board[pos.first][pos.second] = minute;
        }

        minute++;
    }

    // Count squares that were repainted exactly x times
    int result = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (board[i][j] == x - 1) {
                result++;
            }
        }
    }

    cout << result << endl;
    return 0;
}

