typedef array<int, 4> State;

struct Operation {
    char type; // '+' or '/'
    int pos;
};

bool canDivide(const State& state, int pos) {
    return state[pos] % 2 == 0 && state[(pos + 1) % 4] % 2 == 0;
}

State performDivide(const State& state, int pos) {
    State newState = state;
    newState[pos] /= 2;
    newState[(pos + 1) % 4] /= 2;
    return newState;
}

State performAdd(const State& state, int pos) {
    State newState = state;
    newState[pos]++;
    newState[(pos + 1) % 4]++;
    return newState;
}

bool isTargetState(const State& state) {
    return state[0] == 1 && state[1] == 1 && state[2] == 1 && state[3] == 1;
}

vector<Operation> crackSafe(const State& initialState) {
    queue<State> q;
    map<State, pair<State, Operation>> parent;

    q.push(initialState);

    while (!q.empty() && q.size() < 1000000) {
        State current = q.front();
        q.pop();

        if (isTargetState(current)) {
            // Reconstruct path
            vector<Operation> operations;
            State currentState = current;

            while (currentState != initialState) {
                auto [prevState, op] = parent[currentState];
                operations.push_back(op);
                currentState = prevState;
            }

            reverse(operations.begin(), operations.end());
            return operations;
        }

        // Try all possible operations
        for (int i = 0; i < 4; i++) {
            // Try adding
