bool is_better(vector<string>& new_grid, vector<string>& old_grid) {
    if (old_grid.empty()) return true;
    for (size_t i = 0; i < new_grid.size(); i++) {
        if (new_grid[i] < old_grid[i]) return true;
        if (new_grid[i] > old_grid[i]) return false;
    }
    return false;
}

void try_crossword(int w1_idx, int w2_idx, int w3_idx, int w4_idx, int w5_idx, int w6_idx) {
    // Check if total width and height meet minimum requirements
    string& h1 = words[w1_idx];
    string& v1 = words[w2_idx];
    string& h2 = words[w3_idx];
    string& v2 = words[w4_idx];
    string& h3 = words[w5_idx];
    string& v3 = words[w6_idx];

    // Check if words are long enough
    if (h1.size() < 3 || v1.size() < 3 || h2.size() < 3 || v2.size() < 3 || h3.size() < 3 || v3.size() < 3)
        return;

    // Try all possible positions for vertical words
    for (size_t v1_x = 0; v1_x < h1.size(); v1_x++) {
        for (size_t v2_x = v1_x + 1; v2_x < h1.size(); v2_x++) {
            size_t h2_y = 0;
            while (h2_y < v1.size() && h2_y < v3.size()) {
                h2_y++;
                size_t v3_x = 0;
                while (v3_x < h3.size() && v3_x < h2.size()) {
                    v3_x++;

                    // Check intersections
                    if (h1[v1_x] != v1[0]) continue;
                    if (h1[v2_x] != v2[0]) continue;
                    if (v1[h2_y] != h2[0]) continue;
                    if (h2[v3_x] != v3[0]) continue;
                    if (v2[h2_y] != h2[v2_x - v1_x]) continue;
                    if (h3[v1_x - 0 + v3_x] != v3[v1.size() + h2.size() - h2_y]) continue;

                    // Calculate grid dimensions
                    size_t width = max(h1.size(), max(h2.size() + v2_x - v1_x, h3.size() + v1_x - 0));
                    size_t height = v1.size() + h2.size() + v3.size() - h2_y;

                    // Create grid with dots
                    vector<string> current_grid(height, string(width, '.'));

                    // Place h1
                    for (size_t i = 0; i < h1.size(); i++)
                        current_grid[0][i] = h1[i];

                    // Place v1
                    for (size_t i = 0; i < v1.size(); i++)
                        current_grid[i][v1_x] = v1[i];

                    // Place v2
                    for (size_t i = 0; i < v2.size(); i++)
                        current_grid[i][v2_x] = v2[i];

                    // Place h2
                    for (size_t i = 0; i < h2.size(); i++)
                        current_grid[h2_y][v1_x + i] = h2[i];

                    // Place h3
                    for (size_t i = 0; i < h3.size(); i++)
                        current_grid[height - 1][i] = h3[i];

                    // Place v3
                    for (size_t i = 0; i < v3.size(); i++)
                        current_grid[v1.size() + i][v3_x] = v3[i];

                    // Check if this grid is better than the current best
                    if (is_better(current_grid, best_grid)) {
                        best_grid = current_grid;
                    }
                }
            }
        }
    }
}

