#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <set>

using namespace std;

// 6 words
vector<string> words(6);
int n = 6;

// A function to check if a crossword is valid
bool is_valid_crossword(vector<vector<char>>& grid, int rows, int cols) {
    // Check if we have exactly 4 connected regions of dots
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    vector<pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    int regions = 0;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '.' && !visited[i][j]) {
                regions++;
                if (regions > 4) return false;

                // BFS to mark all connected dots
                vector<pair<int, int>> queue;
                queue.push_back({i, j});
                visited[i][j] = true;

                while (!queue.empty()) {
                    auto [x, y] = queue.back();
                    queue.pop_back();

                    for (auto [dx, dy] : directions) {
                        int nx = x + dx, ny = y + dy;
                        if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && 
                            grid[nx][ny] == '.' && !visited[nx][ny]) {
                            visited[nx][ny] = true;
                            queue.push_back({nx, ny});
                        }
                    }
                }
            }
        }
    }

    return regions == 4;
}

// Generate and check each possible crossword configuration
bool generate_crossword(vector<string>& used_words, vector<vector<char>>& grid, int rows, int cols) {
    // Set up the crossword with dots
    grid = vector<vector<char>>(rows, vector<char>(cols, '.'));

    // Vertical words on the left
    int row = 0;
    for (char c : used_words[0]) {
        grid[row++][0] = c;
    }

    // Horizontal words on the top
    int col = 0;
    for (char c : used_words[1]) {
        grid[0][col++] = c;
    }

    // Vertical words on the right
    row = 0;
    for (char c : used_words[2]) {
        grid[row++][cols - 1] = c;
    }

    // Horizontal words on the bottom
    col = 0;
    for (char c : used_words[3]) {
        grid[rows - 1][col++] = c;
    }

    // Inner horizontal word (top)
    int middle_row = (rows - 1) / 3;
    col = 0;
    for (char c : used_words[4]) {
        grid[middle_row][col++] = c;
    }

    // Inner horizontal word (bottom)
    middle_row = 2 * (rows - 1) / 3;
    col = 0;
    for (char c : used_words[5]) {
        grid[middle_row][col++] = c;
    }

    return is_valid_crossword(grid, rows, cols);
}

// Convert grid to string for lexicographical comparison
string grid_to_string(vector<vector<char>>& grid, int rows, int cols) {
    string result;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            result += grid[i][j];
        }
    }
    return result;
}

// Print the grid
void print_grid(vector<vector<char>>& grid, int rows, int cols) {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            cout << grid[i][j];
        }
        cout << endl;
    }
}

int main() {
    // Read the 6 words
    for (int i = 0; i < n; i++) {
        cin >> words[i];
    }

    // Find the maximum dimensions needed for the crossword
    int max_length = 0;
    for (const string& word : words) {
        max_length = max(max_length, (int)word.length());
    }

    bool found = false;
    string best_result;
    vector<vector<char>> best_grid;

    // Try all permutations of words
    vector<int> perm = {0, 1, 2, 3, 4, 5};
    do {
        vector<string> used_words;
        for (int idx : perm) {
            used_words.push_back(words[idx]);
        }

        // Calculate the dimensions of the grid
        int rows = max(used_words[0].length(), used_words[2].length());
        rows = max(rows, max(used_words[4].length(), used_words[5].length()));

        int cols = max(used_words[1].length(), used_words[3].length());
        cols = max(cols, max(used_words[4].length(), used_words[5].length()));

        vector<vector<char>> grid;
        if (generate_crossword(used_words, grid, rows, cols)) {
            found = true;
            string current_result;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    current_result += grid[i][j];
                }
            }

            if (best_result.empty() || current_result < best_result) {
                best_result = current_result;
                best_grid = grid;
            }
        }
    } while (next_permutation(perm.begin(), perm.end()));

    if (!found) {
        cout << "Impossible" << endl;
    } else {
        int rows = best_grid.size();
