using namespace std;

// Structure to represent a position in the grid
struct Position {
    int row, col;
    Position(int r, int c) : row(r), col(c) {}
};

// Structure to represent a word placement
struct Placement {
    int wordIndex;
    Position pos;
    bool horizontal;

    Placement(int idx, int r, int c, bool horiz) : 
        wordIndex(idx), pos(r, c), horizontal(horiz) {}
};

// Function to check if a word can be placed at a position
bool canPlaceWord(const vector<string>& grid, const string& word, int row, int col, bool horizontal) {
    int rows = grid.size();
    if (rows == 0) return false;

    int cols = grid[0].size();

    if (horizontal) {
        if (col + word.length() > cols) return false;

        for (size_t i = 0; i < word.length(); ++i) {
            if (grid[row][col + i] != '.' && grid[row][col + i] != word[i]) {
                return false;
            }
        }
    } else {
        if (row + word.length() > rows) return false;

        for (size_t i = 0; i < word.length(); ++i) {
            if (grid[row + i][col] != '.' && grid[row + i][col] != word[i]) {
                return false;
            }
        }
    }

    return true;
}

// Function to place a word on the grid
void placeWord(vector<string>& grid, const string& word, int row, int col, bool horizontal) {
    if (horizontal) {
        for (size_t i = 0; i < word.length(); ++i) {
            grid[row][col + i] = word[i];
        }
    } else {
        for (size_t i = 0; i < word.length(); ++i) {
            grid[row + i][col] = word[i];
        }
    }
}

// Function to remove a word from the grid
void removeWord(vector<string>& grid, const string& word, int row, int col, bool horizontal) {
    if (horizontal) {
        for (size_t i = 0; i < word.length(); ++i) {
            grid[row][col + i] = '.';
        }
    } else {
        for (size_t i = 0; i < word.length(); ++i) {
            grid[row + i][col] = '.';
        }
    }
}

// Function to check if the grid forms a valid crossword
bool isValidCrossword(const vector<string>& grid) {
    int rows = grid.size();
    if (rows == 0) return false;

    int cols = grid[0].size();

    // Check if there are exactly two inner regions
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    vector<Position> directions = {Position(0, 1), Position(1, 0), Position(0, -1), Position(-1, 0)};

    int innerRegions = 0;

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (grid[i][j] == '.' && !visited[i][j]) {
                // If this is a border region, we don't count it
                bool isBorderRegion = (i == 0 || j == 0 || i == rows - 1 || j == cols - 1);

                // BFS to mark all connected empty cells
                vector<Position> queue = {Position(i, j)};
                visited[i][j] = true;

                for (size_t k = 0; k < queue.size(); ++k) {
                    Position current = queue[k];

                    for (const auto& dir : directions) {
                        int newRow = current.row + dir.row;
                        int newCol = current.col + dir.col;

                        if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols &&
                            grid[newRow][newCol] == '.' && !visited[newRow][newCol]) {
                            visited[newRow][newCol] = true;
                            queue.push_back(Position(newRow, newCol));

                            if (newRow == 0 || newCol == 0 || newRow == rows - 1 || newCol == cols - 1) {
                                isBorderRegion = true;
                            }
                        }
                    }
                }

                if (!isBorderRegion) {
                    innerRegions++;
                }
            }
        }
    }

    return innerRegions == 2;
}

// Recursive function to build the crossword
bool buildCrossword(vector<string>& grid, const vector<string>& words, vector<bool>& used, 
                    vector<Placement>& placements, int wordCount) {
    // If all words are placed, check if it's a valid crossword
    if (wordCount == 6) {
        return isValidCrossword(grid);
    }

    int rows = grid.size();
    int cols = grid[0].size();

    // Try each word in each position
    for (int wordIdx = 0; wordIdx < 6; ++wordIdx) {
        if (!used[wordIdx]) {
            const string& word = words[wordIdx];

            // Try horizontally
            for (int row = 0; row < rows; ++row) {
                for (int col = 0; col <= cols - word.length(); ++col) {
                    if (canPlaceWord(grid, word, row, col, true)) {
                        // Place the word
                        vector<string> backupGrid = grid;
                        placeWord(grid, word, row, col, true);
                        used[wordIdx] = true;
                        placements.push_back(Placement(wordIdx, row, col, true));

                        // Recur
                        if (buildCrossword(grid, words, used, placements, wordCount + 1)) {
                            return true;
                        }

                        // Backtrack
                        used[wordIdx] = false;
                        placements.pop_back();
                        grid = backupGrid;
                    }
                }
            }

            // Try vertically
            for (int col = 0; col < cols; ++col) {
                for (int row = 0; row <= rows - word.length(); ++row) {
                    if (canPlaceWord(grid, word, row, col, false)) {
                        // Place the word
                        vector<string> backupGrid = grid;
                        placeWord(grid, word, row, col, false);
                        used[wordIdx] = true;
                        placements.push_back(Placement(wordIdx, row, col, false));

                        // Recur
                        if (buildCrossword(grid, words, used, placements, wordCount + 1)) {
                            return true;
                        }

                        // Backtrack
                        used[wordIdx] = false;
                        placements.pop_back();
                        grid = backupGrid;
                    }
                }
            }
        }
    }

    return false;
}

