bool canPlaceHorizontal(const vector<string>& grid, const string& word, int r, int c) {
    if (c + word.length() > grid[0].size()) return false;

    for (size_t i = 0; i < word.length(); ++i) {
        if (grid[r][c + i] != '.' && grid[r][c + i] != word[i]) return false;
