void placeHorizontal(vector<string>& grid, const string& word, int r, int c) {
    for (size_t i = 0; i < word.length(); ++i) {
        grid[r][c + i] = word[i];
    }
}

// Check if we can place a word vertically at position (r, c)
bool canPlaceVertical(const vector<string>& grid, const string& word, int r, int c) {
    if (r + word.length() > grid.size()) return false;

    for (size_t i = 0; i < word.length(); ++i) {
        if (grid[r + i][c] != '.' && grid[r + i][c] != word[i]) return false;
    }
    return true;
}

// Place a word vertically at position (r, c)
void placeVertical(vector<string>& grid, const string& word, int r, int c) {
    for (size_t i = 0; i < word.length(); ++i) {
        grid[r + i][c] = word[i];
    }
}

