bool is_valid_position(vector<string>& grid, int x, int y) {
    return x >= 0 && y >= 0 && y < grid.size() && x < grid[y].size();
}

bool can_place_word(vector<string>& grid, string word, Point start, Direction dir) {
    int x = start.x, y = start.y;

    for (char c : word) {
        if (!is_valid_position(grid, x, y)) {
            return false;
        }
        if (grid[y][x] != '.' && grid[y][x] != c) {
            return false;
        }
        x += dir.dx;
        y += dir.dy;
    }

    return true;
}

void place_word(vector<string>& grid, string word, Point start, Direction dir) {
    int x = start.x, y = start.y;

    for (char c : word) {
        grid[y][x] = c;
        x += dir.dx;
        y += dir.dy;
    }
