vector<Pattern> getPatterns(int h, int w) {
    vector<Pattern> patterns;

    // Top horizontal word
    patterns.push_back({0, 0, 0, w-1, w, true});

    // Right vertical word
    patterns.push_back({0, w-1, h-1, w-1, h, false});

    // Bottom horizontal word
    patterns.push_back({h-1, 0, h-1, w-1, w, true});

    // Left vertical word
    patterns.push_back({0, 0, h-1, 0, h, false});

    // Middle horizontal word (crossing)
    int middleRow = h / 2;
    patterns.push_back({middleRow, 0, middleRow, w-1, w, true});

    // Middle vertical word (crossing)
    int middleCol = w / 2;
    patterns.push_back({0, middleCol, h-1, middleCol, h, false});

    return patterns;
}

bool canPlace(const string& word, const Pattern& pattern, char grid[MAX_M][MAX_M]) {
    if (word.length() != pattern.len) return false;

    for (int i = 0; i < pattern.len; i++) {
        int r, c;
        if (pattern.isHorizontal) {
            r = pattern.r1;
            c = pattern.c1 + i;
        } else {
            r = pattern.r1 + i;
            c = pattern.c1;
        }

        if (grid[r][c] != '.' && grid[r][c] != word[i]) {
            return false;
        }
    }

    return true;
}

void placeWord(const string& word, const Pattern& pattern, char grid[MAX_M][MAX_M]) {
    for (int i = 0; i < pattern.len; i++) {
