            r = pattern.r1;
            c = pattern.c1 + i;
        } else {
            r = pattern.r1 + i;
            c = pattern.c1;
        }

        grid[r][c] = word[i];
    }
}

void removeWord(const Pattern& pattern, char grid[MAX_M][MAX_M]) {
    for (int i = 0; i < pattern.len; i++) {
        int r, c;
        if (pattern.isHorizontal) {
            r = pattern.r1;
            c = pattern.c1 + i;
        } else {
            r = pattern.r1 + i;
            c = pattern.c1;
        }

        // Check if this cell is part of another word
        bool isShared = false;
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue;
                if (dr != 0 && dc != 0) continue; // Only check orthogonal cells

                int nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < MAX_M && nc >= 0 && nc < MAX_M && grid[nr][nc] != '.') {
