    int lowerHeight = max(v1len, v3len);

    // Check if words are long enough to form intersections
    if (v1len < 3 || v2len < 3 || v3len < 3) return false;
    if (h1len < 3 || h2len < 3 || h3len < 3) return false;

    // Check crossings
    if (words[h1][0] != words[v1][0]) return false; // top-left crossing
    if (words[h1][leftWidth-1] != words[v2][0]) return false; // top-right crossing
    if (words[h3][0] != words[v1][v1len-1]) return false; // bottom-left crossing
    if (words[h3][rightWidth-1] != words[v3][v3len-1]) return false; // bottom-right crossing

