    if (a <= n && b <= m) {
        for (int i = 0; i <= n - a; i++) {
            for (int j = 0; j <= m - b; j++) {
                int trees = 0;
                for (int k = i; k < i + a; k++) {
                    for (int l = j; l < j + b; l++) {
