#include <iostream>
#include <vector>
#include <stack>

using namespace std;

long long countVisiblePairs(vector<int>& heights) {
    int n = heights.size();
    long long pairsCount = 0;

    // Each hill can see its immediate neighbors
    pairsCount = n;

    // Check visibility in clockwise direction
    for (int i = 0; i < n; i++) {
        stack<pair<int, int>> s;
        s.push({heights[i], i});

        for (int j = 1; j < n; j++) {
            int curr_idx = (i + j) % n;

            while (!s.empty() && heights[curr_idx] > s.top().first) {
                s.pop();
            }

            if (!s.empty() && s.top().first == heights[curr_idx]) {
                continue;
            }

            // Add current hill
            s.push({heights[curr_idx], curr_idx});

            // Count visible pairs (all elements in stack except the last one can see each other)
            if (s.size() >= 2) {
                pairsCount++;
            }
        }
    }

    // Divide by 2 as each pair is counted twice
    return pairsCount / 2;
}

int main() {
    int n;
    cin >> n;

    vector<int> heights(n);
    for (int i = 0; i < n; i++) {
        cin >> heights[i];
    }

    cout << countVisiblePairs(heights) << endl;

    return 0;
}

