    for (int i = 0; i < n; i++) {
        hills[i] = heights[i];
        hills[i + n] = heights[i];
    }

    // For each hill, find the leftmost and rightmost hill it can signal to
    vector<int> left_reach(2 * n, -1);
    vector<int> right_reach(2 * n, 2 * n);

    stack<int> mono_stack;

    // Find leftmost hills (monotonic stack for next greater element)
    for (int i = 0; i < 2 * n; i++) {
        while (!mono_stack.empty() && hills[mono_stack.top()] < hills[i]) {
            left_reach[i] = mono_stack.top();
            mono_stack.pop();
        }
        mono_stack.push(i);
    }

    // Clear stack for next calculation
