using namespace std;

long long countVisiblePairs(const vector<int>& heights) {
    int n = heights.size();
    vector<int> nextGreaterOrEqual(n);
    stack<int> s;

    // Find next greater or equal element in circular array
    for (int i = 2*n - 1; i >= 0; i--) {
        int idx = i % n;
        while (!s.empty() && heights[s.top()] < heights[idx]) {
            s.pop();
        }
        nextGreaterOrEqual[idx] = s.empty() ? -1 : s.top();
        s.push(idx);
    }

    long long result = n; // All adjacent hills can see each other

    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        while (j != i) {
            int minHeight = min(heights[i], heights[j]);

            // Check if there's any hill higher than minHeight between i and j
            bool canSee = true;
            int k = (i + 1) % n;
            while (k != j) {
                if (heights[k] > minHeight) {
                    canSee = false;
                    break;
                }
                k = (k + 1) % n;
            }

            if (canSee) {
                result++;
            }

            // Check the other direction
            canSee = true;
            k = (j + 1) % n;
            while (k != i) {
                if (heights[k] > minHeight) {
                    canSee = false;
                    break;
                }
                k = (k + 1) % n;
            }

            if (canSee) {
                result++;
            }

            j = (j + 1) % n;
        }
    }

    return result / 2; // Each pair is counted twice
}

