bool check(const std::vector<int>& dates) {
    for (int i = 1; i < dates.size(); ++i) {
        if (dates[i] < dates[i-1]) {
            return false;
        }
    }
    return true;
}

std::vector<int> generatePossibleChanges(int date) {
    std::vector<int> result;
    std::string s = std::to_string(date);

    for (int pos = 0; pos < 4; ++pos) {
        char original = s[pos];
        for (char digit = '0'; digit <= '9'; ++digit) {
            if (pos == 0 && digit == '0') continue; // Skip if leading digit becomes 0
            if (digit == original) continue; // Skip if no change

            s[pos] = digit;
            int newDate = std::stoi(s);
            if (newDate >= 1000 && newDate <= 2011) {
                result.push_back(newDate);
            }
            s[pos] = original; // Restore
        }
    }

    // Also include the original date if it's valid
    if (date >= 1000 && date <= 2011) {
        result.push_back(date);
    }

    return result;
}

bool solve(int index, std::vector<int>& result, const std::vector<int>& dates) {
    if (index == dates.size()) {
        return check(result);
    }

    std::vector<int> possibleChanges = generatePossibleChanges(dates[index]);

    for (int newDate : possibleChanges) {
        if (index == 0 || newDate >= result[index-1]) {
            result[index] = newDate;
            if (solve(index+1, result, dates)) {
                return true;
            }
        }
    }

    return false;
}

