bool can_achieve(const vector<double>& a, double target, int k) {
    double give = 0.0, receive = 0.0;
    for (double energy : a) {
        if (energy > target) {
            give += (energy - target);
        } else {
            receive += (target - energy);
        }
    }

    // When giving energy, k% is lost, so what's received is (100-k)% of what's given
    double available_after_loss = give * (100.0 - k) / 100.0;

    return available_after_loss >= receive;
}

