            cout << "Waste";
            continue;
        }

        // Calculate the position of the cell in the sequence
        long long position = (row - 1) * (long long)m + col;

        // Subtract the number of waste cells that come before this cell
        int wastesBefore = 0;
        for (const auto& w : waste) {
            long long wastePos = (w.first - 1) * (long long)m + w.second;
            if (wastePos < position) {
                wastesBefore++;
            }
        }

        // Calculate the effective position after accounting for waste cells
        long long effectivePos = position - wastesBefore;

        // Determine the crop type
