    }

    // Arrays to track duplicate letters in rows and columns
    std::vector<std::vector<bool>> row_duplicates(n, std::vector<bool>(26, false));
    std::vector<std::vector<bool>> col_duplicates(m, std::vector<bool>(26, false));

    // Find duplicates in rows
    for (int i = 0; i < n; i++) {
        std::vector<int> count(26, 0);
        for (int j = 0; j < m; j++) {
            count[grid[i][j] - 'a']++;
        }
        for (int j = 0; j < 26; j++) {
            if (count[j] > 1) {
                row_duplicates[i][j] = true;
            }
        }
    }

    // Find duplicates in columns
    for (int j = 0; j < m; j++) {
        std::vector<int> count(26, 0);
        for (int i = 0; i < n; i++) {
            count[grid[i][j] - 'a']++;
        }
        for (int i = 0; i < 26; i++) {
            if (count[i] > 1) {
                col_duplicates[j][i] = true;
            }
        }
    }

    std::string result;

    // Build the result
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            char letter = grid[i][j];
            int letter_index = letter - 'a';

            // Add to result only if it's not a duplicate in its row or column
            if (!row_duplicates[i][letter_index] && !col_duplicates[j][letter_index]) {
                result += letter;
            }
        }
    }

    std::cout << result << std::endl;

    return 0;
}

