using namespace std;

long long minSelections(long long n, long long m, long long a, long long b) {
    long long result = 0;

    while (a <= b) {
        // Calculate row indices
        long long row_a = (a - 1) / m;
        long long row_b = (b - 1) / m;

        // If a and b are on the same row
        if (row_a == row_b) {
            result++; // Just need one selection for this range
            break;
        }

        // Calculate column indices
        long long col_a = (a - 1) % m;

        // Select until the end of row_a
        long long select_until = (row_a + 1) * m;
        if (select_until > b) {
            select_until = b;
        }

        // If a is not at the beginning of its row
        if (col_a > 0) {
            result++;
            a = select_until + 1;
        } else {
            // Handle full row(s)
            long long full_rows = row_b - row_a;
            if (b == row_b * m + m) { // If b is the last element of its row
                result++;
                break;
            } else {
                // Select all full rows at once if possible
                if (full_rows > 0) {
                    result++;
                    a = row_b * m + 1;
                }
            }
        }
    }

    return result;
}

int main() {
    long long n, m, a, b;
    cin >> n >> m >> a >> b;

    cout << minSelections(n, m, a, b) << endl;

