#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long ll;

int solve(ll n, ll m, ll a, ll b) {
    if (a == b) return 1;  // Only one folder to select

    ll row_a = (a - 1) / m;
    ll col_a = (a - 1) % m;
    ll row_b = (b - 1) / m;
    ll col_b = (b - 1) % m;

    if (row_a == row_b) {
        // All folders in the same row
        return 1;
    }

    ll result = 0;

    // Handle first row
    if (col_a > 0) {
        result++;
        a += (m - col_a);
    }

    // Handle last row
    if (col_b < m - 1) {
        result++;
        b -= (col_b + 1);
    }

    // Handle middle rows
    if (b >= a) {
        ll complete_rows = (b - a + 1) / m;
        ll remaining = (b - a + 1) % m;

        result += (remaining > 0 ? 1 : 0) + (complete_rows > 0 ? 1 : 0);
    }

    return result;
}

int main() {
    ll n, m, a, b;
    cin >> n >> m >> a >> b;
    cout << solve(n, m, a, b) << endl;
    return 0;
