std::pair<long long, long long> addFractions(const std::pair<long long, long long>& a, const std::pair<long long, long long>& b) {
    long long lcmVal = lcm(a.second, b.second);
    long long num = a.first * (lcmVal / a.second) + b.first * (lcmVal / b.second);
    long long den = lcmVal;
    long long gcdVal = std::gcd(num, den);
    return {num / gcdVal, den / gcdVal};
}

std::pair<long long, long long> mulFractions(const std::pair<long long, long long>& a, const std::pair<long long, long long>& b) {
    long long num = a.first * b.first;
    long long den = a.second * b.second;
    long long gcdVal = std::gcd(num, den);
    return {num / gcdVal, den / gcdVal};
}

std::pair<long long, long long> solve(int n) {
    if (n == 1) {
        return {0, 1}; // 0 tosses needed
    }

    if (n == 2) {
        return {1, 1}; // 1 toss needed
    }

    std::vector<std::pair<long long, long long>> memo(n + 1, {-1, 1});
    memo[1] = {0, 1};
    memo[2] = {1, 1};

    for (int k = 3; k <= n; k++) {
        int largest_power_of_2 = 1;
        while (largest_power_of_2 * 2 <= k) {
            largest_power_of_2 *= 2;
        }

        // E(k) = 1 + [largest_power_of_2/k * E(k - largest_power_of_2) + (k - largest_power_of_2)/k * E(k)]

        std::pair<long long, long long> term1 = {1, 1}; // 1

        std::pair<long long, long long> prob1 = {largest_power_of_2, k};
        std::pair<long long, long long> term2 = mulFractions(prob1, memo[k - largest_power_of_2]);

        std::pair<long long, long long> prob2 = {k - largest_power_of_2, k};
        // For E(k) on right side: E(k) = [1 + term2 + prob2*E(k)] => E(k)*(1-prob2) = 1 + term2
        std::pair<long long, long long> one_minus_prob2 = {k - (k - largest_power_of_2), k};

        // Calculate [1 + term2] / one_minus_prob2
        std::pair<long long, long long> numerator = addFractions(term1, term2);
        memo[k] = mulFractions(numerator, {one_minus_prob2.second, one_minus_prob2.first});
    }

    return memo[n];
}

