    vector<string> getAllRotations() const {
        // Original cube arrangement: 
        // faces[0] = top, faces[1] = front, faces[2] = right, 
        // faces[3] = back, faces[4] = left, faces[5] = bottom

        vector<int> indices = {0, 1, 2, 3, 4, 5};
        unordered_set<string> uniqueRotations;

        // Rotations around x-axis (4 positions)
        for (int x = 0; x < 4; x++) {
            // Rotations around y-axis (4 positions per x rotation)
            for (int y = 0; y < 4; y++) {
                // Rotations around z-axis (6 positions per x,y rotation pair)
