        if (i % 2 == 1) {  // Odd moves: swap left and middle (0 and 1)
            if (x == 0) x = 1;
            else if (x == 1) x = 0;
        } else {  // Even moves: swap middle and right (1 and 2)
            if (x == 1) x = 2;
            else if (x == 2) x = 1;
        }
    }

