        dp[i] = rings[i].h;
        for (int j = 0; j < i; j++) {
            if (rings[j].b > rings[i].a && rings[j].b >= rings[i].b) {
                dp[i] = max(dp[i], dp[j] + rings[i].h);
            }
        }
