int solve(ll a, ll b, ll h, ll w, int n, vector<int>& extensions) {
    // Check if we can already place the rectangle
    if ((h >= a && w >= b) || (h >= b && w >= a)) {
        return 0;
    }

    sort(extensions.rbegin(), extensions.rend()); // Sort in descending order

    int answer = n + 1; // Initialize with impossible value

    // Try all possible 2^n subsets of extensions
    // We'll use bitmasks to represent subsets
    int max_mask = 1 << min(n, 30); // To prevent overflow

    for (int mask = 1; mask < max_mask; ++mask) {
        ll new_h = h;
        ll new_w = w;
        int count_extensions = 0;

        for (int i = 0; i < n && i < 30; ++i) {
            if (mask & (1 << i)) {
                count_extensions++;

                // For each extension, decide whether to apply it to height or width
                // Choose the dimension that needs more expansion
                if (new_h * extensions[i] / a < new_w * extensions[i] / b) {
                    new_h *= extensions[i];
                } else {
                    new_w *= extensions[i];
                }

                // If rectangle fits, update answer
                if ((new_h >= a && new_w >= b) || (new_h >= b && new_w >= a)) {
                    answer = min(answer, count_extensions);
                    break;
                }
            }
        }
    }

    return answer > n ? -1 : answer;
}

