#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

bool canFit(long long a, long long b, long long h, long long w) {
    return (a <= h && b <= w) || (a <= w && b <= h);
}

int solve(long long a, long long b, long long h, long long w, vector<int>& extensions) {
    if (canFit(a, b, h, w)) {
        return 0;
    }

    int n = extensions.size();
    sort(extensions.rbegin(), extensions.rend());

    vector<pair<long long, long long>> states;
    states.push_back({h, w});

    for (int i = 0; i < n; i++) {
        int extensionSize = extensions[i];
        int currentStates = states.size();

        for (int j = 0; j < currentStates; j++) {
            long long currentH = states[j].first;
            long long currentW = states[j].second;

            // Apply extension to height
            long long newH = currentH * extensionSize;
            if (canFit(a, b, newH, currentW)) {
                return i + 1;
            }
            states.push_back({newH, currentW});

            // Apply extension to width
            long long newW = currentW * extensionSize;
            if (canFit(a, b, currentH, newW)) {
                return i + 1;
            }
            states.push_back({currentH, newW});
        }
    }

    return -1;
}

int main() {
    long long a, b, h, w, n;
    cin >> a >> b >> h >> w >> n;

    vector<int> extensions(n);
    for (int i = 0; i < n; i++) {
        cin >> extensions[i];
    }

    cout << solve(a, b, h, w, extensions) << endl;

    return 0;
}

