using namespace std;

// Function to compute the log-likelihood for Poisson distribution
double poissonLogLikelihood(const vector<int>& data, double lambda) {
    double logLikelihood = 0.0;
    for (int k : data) {
        logLikelihood += k * log(lambda) - lambda - lgamma(k + 1);
    }
    return logLikelihood;
}

// Function to compute the log-likelihood for Uniform distribution
double uniformLogLikelihood(const vector<int>& data, int P) {
    double logProb = -log(2 * P + 1);
    double logLikelihood = 0.0;

    for (int k : data) {
        if (k >= 0 && k <= 2 * P) {
            logLikelihood += logProb;
        } else {
            // If any value is outside the range, it's effectively impossible under uniform
            return -INFINITY;
        }
    }

    return logLikelihood;
}

// Function to estimate the parameter P for both distributions
double estimateP(const vector<int>& data) {
    double sum = 0;
    int max_val = 0;
    for (int k : data) {
        sum += k;
        max_val = max(max_val, k);
    }

    // For Poisson, lambda = P and mean = lambda
    // For Uniform, mean = P and max value is approximately 2P
    double mean = sum / data.size();

    // If max value is significantly larger than 2 * mean, it's more likely Poisson
    // Otherwise, estimate P as mean for Poisson and max/2 for Uniform
    return mean;
}

// Function to determine the distribution type
string determineDistribution(const vector<int>& data) {
    // Estimate P (or lambda) from the data
    double P = estimateP(data);

    // Compute log-likelihoods for both distributions
    double poissonLL = poissonLogLikelihood(data, P);
    double uniformLL = uniformLogLikelihood(data, ceil(P));

    // Return the distribution with higher log-likelihood
    return (poissonLL > uniformLL) ? "poisson" : "uniform";
}

