    vector<int> freq(max_val + 1, 0);

    for (int x : data) {
        freq[x]++;
    }

    // Estimate parameter (mean) for Poisson distribution
    double mean = 0;
    for (int i = 0; i < data.size(); i++) {
        mean += data[i];
    }
    mean /= data.size();

    // Calculate expected Poisson frequencies
    vector<double> expected_poisson(max_val + 1, 0);
    double lambda = mean;

    double factorial = 1.0;
    double exp_lambda = exp(-lambda);

    expected_poisson[0] = exp_lambda * 250;

    for (int k = 1; k <= max_val; k++) {
        factorial *= k;
        expected_poisson[k] = exp_lambda * pow(lambda, k) / factorial * 250;
    }

    // Calculate expected Uniform frequencies
    // Estimate P for uniform distribution (max value / 2)
    int P = (max_val + 1) / 2;
    double uniform_prob = 1.0 / (2 * P + 1);
    double expected_uniform_freq = 250 * uniform_prob;

