double factorial(int n) {
    double result = 1.0;
    for (int i = 2; i <= n; ++i) {
        result *= i;
    }
    return result;
}

double poissonPDF(int k, double lambda) {
    return exp(-lambda) * pow(lambda, k) / factorial(k);
}

double uniformPDF(int k, int a, int b) {
    if (k >= a && k <= b) {
        return 1.0 / (b - a + 1);
    }
    return 0.0;
}

