double uniformLogLikelihood(const vector<int>& data, int N) {
    double logProb = -log(N + 1);  // Uniform probability from 0 to N
    double logLikelihood = 0.0;
    for (int x : data) {
        if (x > N) return -INFINITY;  // Invalid observation for this uniform
        logLikelihood += logProb;
    }
    return logLikelihood;
}

