using namespace std;

// Calculate chi-square statistic for Poisson distribution
double calc_poisson_chi_square(const vector<int>& counts, double lambda, int total_samples) {
    double chi_square = 0.0;

    // Calculate expected frequencies for Poisson distribution
    vector<double> expected;
    double sum_expected = 0.0;

    // Calculate e^(-lambda)
    double exp_neg_lambda = exp(-lambda);
    double poisson_prob = exp_neg_lambda;

    // Calculate probabilities for each value
    int max_idx = counts.size() - 1;
    for (int i = 0; i <= max_idx; ++i) {
        if (i > 0) {
            poisson_prob *= lambda / i;
        }

        double expected_count = poisson_prob * total_samples;
        expected.push_back(expected_count);
        sum_expected += expected_count;
    }

    // Group categories with expected count < 5
    int current_bin_start = 0;
    double current_bin_expected = 0;
    int current_bin_observed = 0;

    for (int i = 0; i <= max_idx; ++i) {
        current_bin_expected += expected[i];
        current_bin_observed += counts[i];

        if (current_bin_expected >= 5 || i == max_idx) {
            if (current_bin_expected > 0) {
                chi_square += pow(current_bin_observed - current_bin_expected, 2) / current_bin_expected;
            }
            current_bin_expected = 0;
            current_bin_observed = 0;
            current_bin_start = i + 1;
        }
    }

    return chi_square;
}

// Calculate chi-square statistic for uniform distribution
double calc_uniform_chi_square(const vector<int>& counts, int min_val, int max_val, int total_samples) {
    double chi_square = 0.0;
    int range = max_val - min_val + 1;
    double expected_per_bin = static_cast<double>(total_samples) / range;

    // Group categories with expected count < 5
    int current_bin_start = 0;
    double current_bin_expected = 0;
    int current_bin_observed = 0;

    for (int i = 0; i < counts.size(); ++i) {
        int idx = min_val + i;
        if (idx >= 0 && idx < counts.size()) {
            current_bin_expected += expected_per_bin;
            current_bin_observed += counts[i];

            if (current_bin_expected >= 5 || i == counts.size() - 1) {
                if (current_bin_expected > 0) {
                    chi_square += pow(current_bin_observed - current_bin_expected, 2) / current_bin_expected;
                }
                current_bin_expected = 0;
                current_bin_observed = 0;
                current_bin_start = i + 1;
            }
        }
    }

    return chi_square;
}

string determine_distribution(const vector<int>& answers, int P) {
    // Shift answers by adding P back (since they were subtracted by P)
    vector<int> shifted_answers;
    for (int ans : answers) {
        shifted_answers.push_back(ans + P);
    }

    // Find the range of values
    int min_val = *min_element(answers.begin(), answers.end());
    int max_val = *max_element(answers.begin(), answers.end());
    int range = max_val - min_val + 1;

    // Create frequency counts
    vector<int> counts(range, 0);
    for (int ans : answers) {
        counts[ans - min_val]++;
    }

    // Calculate sample mean
    double shifted_mean = 0;
    for (int ans : shifted_answers) {
        shifted_mean += ans;
    }
    shifted_mean /= shifted_answers.size();

    // Calculate chi-square statistics
    double poisson_chi_square = calc_poisson_chi_square(counts, shifted_mean, answers.size());
    double uniform_chi_square = calc_uniform_chi_square(counts, min_val, max_val, answers.size());

    // Calculate degrees of freedom
    int dof_poisson = max(1, range - 1 - 1);  // -1 for estimated parameter lambda
    int dof_uniform = max(1, range - 1);      // no estimated parameters for uniform

    // Calculate p-values (higher p-value means better fit)
    // Since we don't have a p-value calculation function, we'll use the reduced chi-square statistic
    double reduced_poisson = poisson_chi_square / dof_poisson;
    double reduced_uniform = uniform_chi_square / dof_uniform;

    // Return the distribution with the lower reduced chi-square statistic
    return (reduced_poisson <= reduced_uniform) ? "poisson" : "uniform";
}

int main() {
