#include <iostream>
#include <vector>
#include <unordered_set>
#include <numeric>

using namespace std;

bool canDivide(const vector<long long>& a) {
    int n = a.size();
    long long totalSum = accumulate(a.begin(), a.end(), 0LL);

    // If total sum is odd, we cannot divide it into two equal parts
    if (totalSum % 2 != 0) return false;

    long long targetSum = totalSum / 2;
    unordered_set<long long> possibleSums;

    long long prefixSum = 0;
    for (int i = 0; i < n - 1; i++) {
        prefixSum += a[i];
        long long suffixSum = totalSum - prefixSum;

        // Check if we can already divide without moving
        if (prefixSum == suffixSum) return true;

        // Try to move one element from prefix to suffix
        if (prefixSum > targetSum) {
            long long diff = prefixSum - targetSum;
            if (diff <= prefixSum && possibleSums.find(diff) != possibleSums.end()) {
                return true;
            }
        }

        // Try to move one element from suffix to prefix
        if (prefixSum < targetSum) {
            long long diff = targetSum - prefixSum;
            if (diff <= suffixSum && find(a.begin(), a.end(), diff) != a.end()) {
                return true;
            }
        }

        possibleSums.insert(a[i]);
    }

    // Check all possible moves
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;

            vector<long long> modified = a;
            long long element = modified[i];
            modified.erase(modified.begin() + i);
            modified.insert(modified.begin() + j, element);

            long long currentSum = 0;
            for (int k = 0; k < n - 1; k++) {
                currentSum += modified[k];
                if (currentSum == totalSum - currentSum) {
                    return true;
                }
            }
        }
    }

    return false;
}

int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    cout << (canDivide(a) ? "YES" : "NO") << endl;

    return 0;
}

