        for (int j = 0; j <= n; j++) {
            if (i == j || i + 1 == j) continue; // No effective move

            ll new_sum;
            if (j <= i) {
                // Insert before i, prefix gets a[i] added
                new_sum = without_ai + a[i];
            } else {
                // Insert after i, prefix doesn't change
