        if (prefixSum[i] == targetSum) {
            return true;
        }
    }

    // Try moving each element
    for (int i = 0; i < n; i++) {
        // Skip this element from the array
        long long remainingSum = totalSum - a[i];

        // If remaining sum is odd, we can't divide it evenly
        if (remainingSum % 2 != 0) {
            continue;
