bool canMakeNonIncreasing(const std::vector<int>& a, const std::vector<int>& b) {
    int n = a.size();

    // Try to make a decreasing sequence by finding a position where we can place a smaller number after a larger one
    for (int i = 0; i < n - 1; i++) {
        // Check if a[i] or a[i+1] is a zero (can be replaced)
        bool a_i_is_zero = (a[i] == 0);
        bool a_i_plus_1_is_zero = (a[i + 1] == 0);

        if (!a_i_is_zero && !a_i_plus_1_is_zero) {
            // If a[i] > a[i+1], we already have a non-increasing sequence
            if (a[i] > a[i + 1]) {
                return true;
            }
            continue;
        }

        // If a[i] is not a zero but a[i+1] is a zero
        if (!a_i_is_zero && a_i_plus_1_is_zero) {
            // Find any element in b smaller than a[i]
            for (int val : b) {
                if (val < a[i]) {
                    return true;
                }
            }
        }

        // If a[i] is a zero but a[i+1] is not a zero
        if (a_i_is_zero && !a_i_plus_1_is_zero) {
            // Find any element in b larger than a[i+1]
            for (int val : b) {
                if (val > a[i + 1]) {
                    return true;
                }
            }
        }

        // If both a[i] and a[i+1] are zeros
        if (a_i_is_zero && a_i_plus_1_is_zero) {
            // If b has at least two elements, we can place them in decreasing order
            if (b.size() >= 2) {
                return true;
            }
        }
    }

    return false;
}

