using namespace std;

bool solve(int n, const vector<int>& leaders, vector<int>& perm) {
    vector<bool> used(n + 1, false);

    for (int i = 0; i < n; i++) {
        perm[i] = 0;
    }

    for (int i = 0; i < (int)leaders.size() - 1; i++) {
        int curr = leaders[i];
        int next = leaders[i + 1];

        int steps = (next - curr + n) % n;
        if (steps == 0) steps = n;

        if (perm[curr - 1] != 0) {
            if (perm[curr - 1] != steps) {
                return false;
            }
        } else {
            if (steps > 0 && steps <= n && !used[steps]) {
                perm[curr - 1] = steps;
                used[steps] = true;
            } else {
                return false;
            }
        }
    }

