#include <iostream>
#include <vector>
#include <algorithm>
#include <set>

using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> cards(n);
    for (int i = 0; i < n; ++i) {
        cin >> cards[i];
    }

    multiset<int> deck(cards.begin(), cards.end());
    long long operations = 0;
    int lastMin = -1;

    for (int i = 0; i < n; ++i) {
        int currentMin = *deck.begin();

        if (cards[i] == currentMin) {
            // Found a minimum card, remove it
            operations++;
            deck.erase(deck.find(cards[i]));
            lastMin = currentMin;
        } else {
            // Put the card at the bottom, count one operation
            operations++;

            // If we haven't removed any minimum element before the current card
            // and the current minimum is the same as the last time, we need to
            // process all cards left in the deck to find the next minimum
            if (lastMin == currentMin) {
                operations += deck.size();
                break;
            }

            // Process all cards until we find all instances of the current minimum
            int count = distance(deck.begin(), deck.upper_bound(currentMin));
            operations += count;

            // Remove all instances of the current minimum
            auto it = deck.begin();
            while (it != deck.end() && *it == currentMin) {
                it = deck.erase(it);
            }

            lastMin = currentMin;

            // If we've processed all cards, we're done
            if (deck.empty()) {
                break;
            }

            // Adjust i to continue from the correct position
            i += count - 1;
        }
    }

    cout << operations << endl;
    return 0;
}

