    std::vector<char> clockwise = {'^', '>', 'v', '<'};

    // Create a map for faster position lookup
    std::unordered_map<char, int> posMap;
    for (int i = 0; i < 4; i++) {
        posMap[clockwise[i]] = i;
    }

    // Find positions of start and end in the clockwise array
    int startPos = posMap[start];
    int endPos = posMap[end];

    // Calculate position after n seconds in clockwise direction
    int cwPos = (startPos + (n % 4)) % 4;

    // Calculate position after n seconds in counterclockwise direction
    int ccwPos = (startPos - (n % 4) + 4) % 4;

    // Check if end position matches either direction
    if (cwPos == endPos && ccwPos != endPos) {
        std::cout << "cw" << std::endl;
    } else if (cwPos != endPos && ccwPos == endPos) {
        std::cout << "ccw" << std::endl;
    } else {
        std::cout << "undefined" << std::endl;
    }

    return 0;
}

