    while (step < n) {
        vector<int> indices;
        for (int i = step; i <= n; i += step * 2) {
            for (int j = i; j < min(i + step, n + 1); ++j) {
                indices.push_back(j);
            }
        }

        if (indices.empty()) break;

        int xor_val = ask(indices);
        int expected_xor;

        if (indices.size() % 2 == 0) {
            expected_xor = 0;
